'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='pul'?'Collins: https://www.collinsdictionary.com/dictionary/english/pul':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('proxy','Proxy entered English through Middle English and Anglo-French forms connected with procuracy or agency; its central idea is acting in another person’s place.',[C('proxy.s1','代理人；代表','Mina could not attend the hearing, so she appointed her colleague as her proxy to speak and vote for her.','米娜无法出席听证会，于是指定同事作代理人，替她发言和投票。','Mina appointed her colleague / as her proxy / to speak and vote for her.','proxy.s1 指获授权代替他人行事的人。','同事得到授权，替米娜出席并投票。'),C('proxy.s2','代理权；委托书','The shareholders signed a proxy authorizing the trustee to cast their votes at the annual meeting.','股东签署了委托书，授权受托人在年度会议上代为投票。','The shareholders signed a proxy / authorizing the trustee / to cast their votes.','proxy.s2 指允许他人代行权利的书面授权或代理权。','文件明确授权受托人代表股东投票。'),C('proxy.s3','代理服务器','The school routed student devices through a proxy to filter harmful websites and log network traffic.','学校让学生设备经由代理服务器连接网络，以过滤有害网站并记录流量。','The school routed student devices / through a proxy / to filter websites and log traffic.','proxy.s3 指代用户转发网络请求的中间服务器。','服务器处于用户设备与互联网之间并处理请求。')],M('The voter cast a proxy to her brother at the meeting, although she had only asked him to act for her.','The voter appointed her brother as her proxy at the meeting.','proxy 是代行者或授权本身；不能说 cast a proxy 来表示指定代理人。','collocation'),[q('Who spoke and voted at the hearing for Mina?','her appointed colleague','the hearing clerk who counted the ballots','a server filtering student websites','同事被指定为代理人，替米娜出席。',1,'context'),q('What did the signed proxy authorize the trustee to do?','cast the shareholders’ votes','filter websites on student devices','attend the hearing as a clerk','委托书授权受托人代股东投票。',2,'context'),q('What role did the school proxy perform?','forwarding network requests and filtering access','voting for absent shareholders','speaking for Mina at a hearing','学校的 proxy 是转发网络请求的代理服务器。',3,'meaning'),q('Which sentence uses proxy for a person?','A director appointed Lee as her proxy for the vote.','A proxy server cached the requested page.','The signed proxy granted voting authority.','代替董事投票的 Lee 是代理人。',1,'grammar')]);
P('prudence','Prudence comes through Old French prudence from Latin prudentia, “foresight or practical wisdom”; it is careful, sensible judgment.',C('prudence.s1','谨慎；审慎','As a matter of prudence, the treasurer kept a reserve fund instead of spending every dollar on the first proposal.','出于谨慎，财务主管保留了储备金，没有把每一美元都投到第一个方案上。','As a matter of prudence / the treasurer kept a reserve fund / instead of spending every dollar.','prudence 指考虑后果并作出明智判断的谨慎。','保留备用资金体现了对未来风险的考量。'),M('It was prudence to spend the entire emergency reserve on an untested idea before checking the costs.','It was imprudent to spend the entire reserve before checking the costs.','未经核算就花光应急储备是轻率行为，不是谨慎判断。','meaning'),[q('What showed the treasurer’s prudence?','keeping some money in reserve','spending every dollar on the first proposal','refusing to compare any future costs','财务主管留出储备金体现审慎。'),q('What does prudence describe?','careful judgment that considers consequences','a written authority to vote for another person','a server that forwards internet requests','prudence 指考虑后果的谨慎判断。',1,'meaning'),q('Which decision best demonstrates prudence before a costly purchase?','checking the budget and likely risks first','buying immediately because the first offer sounds exciting','using the emergency reserve without reviewing the price','先核对预算和风险是审慎的做法。',1,'context'),q('Which Latin word is the source of prudence?','prudentia, “foresight or practical wisdom”','pseudonymos, “false name”','psyche, “mind or soul”','prudence 经法语来自表示远见和实践智慧的拉丁词。',1,'word-formation')]);
P('prudent','Prudent came from Old French prudent and Latin prudentem, associated with foreseeing; it describes a person or choice showing sensible care.',C('prudent.s1','谨慎的；审慎的','It was prudent of Hana to compare the loan terms and ask about fees before signing.','花奈在签字前比较贷款条款并询问费用，这样做很审慎。','It was prudent of Hana / to compare the loan terms / before signing.','prudent 描述谨慎、明智并考虑后果的人或做法。','签约前比较条款和费用可避免不必要风险。'),M('It was prudent of Hana to sign the first loan offer without reading the fees or repayment terms.','It was prudent of Hana to read the fees and repayment terms before signing.','未读费用与还款条款就签约是轻率的；先阅读才审慎。','meaning'),[q('What made Hana’s decision prudent?','she compared terms and checked fees before signing','she accepted the first offer without reading it','she ignored the repayment schedule','签署前比较条款、核对费用体现审慎。'),q('Which person is prudent with a repair estimate?','one who compares the work and cost before agreeing','one who pays immediately without asking what is included','one who discards every written estimate','先核对维修范围和费用的人做事谨慎。',1,'context'),q('What does prudent mean in “a prudent investment”?','carefully considered and sensible','secretly made under another person’s name','related to the mind rather than the body','prudent 表示经过审慎考虑、合理明智。',1,'meaning'),q('Which noun names the quality of being prudent?','prudence','publicity','psyche','prudence 是 prudent 所描述的审慎品质。',1,'word-formation')]);
P('prune','Prune as a verb has an uncertain early history, probably through French forms meaning to trim; prune as a dried plum comes through Old French from Latin prunum. The assigned source senses cover trimming, removing excess, and the fruit.',[C('prune.s1','修剪（枝条）','The gardener pruned the rosebush in late winter so new shoots could grow without crossing branches.','园丁在冬末修剪玫瑰丛，让新枝生长时不会彼此交错。','The gardener pruned the rosebush / in late winter / so new shoots could grow freely.','prune.s1 指剪掉树木或植物多余枝条，以利生长或成形。','修剪目标是避免枝条交错并促进新枝生长。'),C('prune.s2','删减；精简','The editor pruned two repetitive paragraphs from the report while keeping its central evidence intact.','编辑删去了报告中两段重复内容，同时保留了核心证据。','The editor pruned two repetitive paragraphs / from the report / while keeping the evidence intact.','prune.s2 作动词可比喻为删去文本或计划中的多余部分。','被删的是重复段落，核心证据没有删掉。'),C('prune.s3','梅干；西梅干','For the trail snack, Omar packed a few prunes with nuts because the dried fruit travels well.','奥马尔为徒步零食装了几颗西梅干和坚果，因为这种干果便于携带。','Omar packed a few prunes / with nuts / for a portable trail snack.','prune.s3 是指梅干或西梅干的名词。','例句中 prunes 与坚果一起作便携干果零食。')],M('The editor pruned the report by adding several pages of repeated background and deleting none of the extra material.','The editor pruned the report by deleting repeated background while preserving its key evidence.','prune 的比喻义是删去多余部分，不是增添重复内容。','meaning'),[q('Why did the gardener prune the rosebush?','to keep branches from crossing and make room for new shoots','to dry the roses into a portable snack','to add two repetitive paragraphs','修剪让新枝生长并避免枝条交错。',1,'context'),q('What did the editor prune from the report?','two repetitive paragraphs','the central evidence that the report needed','a branch from the rosebush','编辑删去了重复段落。',2,'context'),q('Which food is a prune?','a dried plum packed with nuts','a fresh rose petal','a paragraph removed from a report','prune 作名词时指梅干。',3,'meaning'),q('Which sentence uses prune figuratively?','The committee pruned redundant steps from the application process.','The gardener pruned a branch after flowering.','She ate a prune on the walk.','删去申请流程中的冗余步骤是比喻用法。',2,'meaning')]);
P('pry','Pry has an uncertain early origin. English uses it for intrusive looking or questioning and for forcing something open with leverage; the contexts distinguish those established senses.',[C('pry.s1','打探；窥探','The reporter refused to pry into the family’s private medical history after they asked for privacy.','家人要求保护隐私后，记者拒绝打探他们的私人病史。','The reporter refused to pry / into the family’s private history / after they asked for privacy.','pry.s1 指以冒犯的方式打听或窥探隐私。','家人明确要求隐私，记者不再打探。'),C('pry.s2','撬开','A rescue worker used a flat bar to pry the jammed hatch open after the power failed.','断电后，救援人员用扁撬棍撬开卡住的舱门。','A rescue worker used a flat bar / to pry the jammed hatch open / after the power failed.','pry.s2 指用工具施力撬开某物。','扁撬棍施加杠杆力使卡住的舱门打开。')],M('The reporter pry into the family’s private history last night despite their request for privacy.','The reporter pried into the family’s private history last night despite their request for privacy.','叙述过去发生的事，动词 pry 应用过去式 pried。','grammar'),[q('What did the reporter avoid doing?','asking intrusive questions about private medical history','using a flat bar to open the hatch','asking the rescue crew about the power failure','记者没有打探家人的私人病史。',1,'context'),q('How did the rescue worker open the jammed hatch?','by levering it with a flat bar','by asking the family for private records','by waiting for the failed power to return','救援人员用扁撬棍撬开舱门。',2,'context'),q('Which action is prying into someone’s private life?','pressing them for details they have asked to keep confidential','using a bar to lift a stuck cover','asking permission before discussing a public schedule','追问对方要求保密的细节属于窥探隐私。',1,'meaning'),q('Which sentence uses pry in the physical sense?','The mechanic pried the lid off with a small lever.','The columnist pried into the actor’s medical records.','The neighbor pried for gossip about the family.','用小杠杆撬开盖子是 pry 的物理用法。',2,'meaning')]);
P('prying','Prying is the present participle of pry and an adjective for intrusive curiosity; the adjective usually describes questions, eyes, or people crossing privacy boundaries.',C('prying.s1','爱打听隐私的；窥探的','She closed the folder before the prying visitor could read the confidential names inside.','爱打听隐私的访客还没来得及读里面的保密姓名，她就合上了文件夹。','She closed the folder / before the prying visitor / could read the confidential names.','prying.s1 描写冒犯隐私、爱打探的行为或人。','访客试图偷看保密姓名，表现出窥探。'),M('The visitor was prying when she carefully respected the closed folder and never asked about private names.','The visitor was prying when she tried to read the confidential names in the closed folder.','尊重文件隐私并不属于窥探；试图偷看才是 prying。','meaning'),[q('What did the prying visitor try to read?','the confidential names in the folder','the public schedule on the wall','the instructions for the flat bar','访客想偷看文件中的保密姓名。'),q('What does prying describe?','intrusive curiosity about something private','careful preparation for a meeting','a medical specialty treating mental illness','prying 描写侵犯隐私的好奇行为。',1,'meaning'),q('Which is a prying question?','“What was the confidential diagnosis you asked us not to discuss?”','“Where is the public meeting room?”','“May I help carry this folder?”','追问已要求保密的诊断属于窥探隐私。',1,'context'),q('How is prying related to pry?','it is the -ing form used as an adjective for intrusive behavior','it is the past tense of prune','it is a noun meaning written permission to vote','prying 是 pry 的 -ing 形式，也可作形容词。',1,'grammar')]);
P('pseudonym','Pseudonym comes from Greek pseudōnymos, “having a false name,” from pseudēs “false” and onyma “name”; it can be an author’s pen name or any assumed identity.',[C('pseudonym.s1','笔名','The novelist published the first two mysteries under a pseudonym so readers would judge the stories on their own.','这位小说家用笔名出版了前两部悬疑小说，希望读者仅凭故事本身作判断。','The novelist published the mysteries / under a pseudonym / so readers would judge the stories independently.','pseudonym.s1 指作者发表作品时使用的笔名。','小说家以另一个名字发表作品。'),C('pseudonym.s2','假名；化名','During the investigation, the witness used a pseudonym on the public tip form to protect her identity.','调查期间，证人为了保护身份，在公开举报表上使用了化名。','The witness used a pseudonym / on the public tip form / to protect her identity.','pseudonym.s2 泛指为隐藏真实身份而使用的假名。','举报表上的名字用于保护证人的真实身份。')],M('The novelist used a pseudonym by printing her full legal name on every cover to conceal who wrote the books.','The novelist used a pseudonym by printing an assumed name on each cover instead of her legal name.','公开使用法定姓名不能隐藏作者身份；化名应替代真实姓名。','meaning'),[q('Why did the novelist publish under a pseudonym?','so readers would focus on the stories rather than her identity','so the witness could report a tip about the investigation','so the books would be printed with no title','作者使用笔名是为了让读者关注故事而非身份。',1,'context'),q('Why did the witness use a pseudonym on the tip form?','to protect her real identity','to announce her legal name to the public','to identify the novel’s author','证人用化名保护真实身份。',2,'context'),q('Which is an author’s pseudonym?','a made-up byline used instead of the writer’s legal name','the writer’s unaltered name on an official passport','a book’s ISBN printed on its cover','替代法定姓名的作者署名是笔名。',1,'meaning'),q('Which Greek elements form pseudonym?','pseudēs “false” + onyma “name”','psyche “mind” + iatros “doctor”','poli “city” + nomos “law”','pseudonym 由希腊语“假”和“名字”构成。',1,'word-formation')]);
P('pseudoscience','Pseudoscience combines Greek pseudo- “false” with science; it presents claims as scientific while lacking reliable evidence or testable methods.',[C('pseudoscience.s1','伪科学（总称）','The review rejected the treatment as pseudoscience because its promoters offered testimonials but no controlled evidence.','评审认定这种疗法属于伪科学，因为推广者只提供个人证言，没有对照证据。','The review rejected the treatment / as pseudoscience / because controlled evidence was absent.','pseudoscience.s1 指以科学面貌包装、却缺乏可靠证据的信念或做法。','只有证言而无受控证据，支撑不了科学主张。'),C('pseudoscience.s2','某种伪科学说法','The claim that a bracelet can diagnose infection from a person’s aura is a pseudoscience, not a validated test.','声称手环能从人的气场诊断感染，是一种伪科学说法，并非经过验证的检测。','The bracelet claim / is a pseudoscience / rather than a validated diagnostic test.','pseudoscience.s2 可数用法指某一项冒充科学的具体主张或体系。','该具体诊断说法没有经过验证。')],M('The panel called the bracelet a pseudoscience because several controlled trials repeatedly confirmed that it accurately detected infection.','The panel called the bracelet claim pseudoscience because no controlled trial supported its diagnostic accuracy.','若多项受控试验证实准确性，就不能据此称其为伪科学。','meaning'),[q('Why did the review reject the treatment?','its promoters supplied testimonials but no controlled evidence','a series of controlled studies confirmed its effect','the treatment was described in a scientific journal','评审指出缺少对照证据，只有证言。',1,'context'),q('What was the bracelet claim said to do?','diagnose infection from a person’s aura','measure the length of a person’s arm','publish a study under a pen name','这项具体说法声称可从气场诊断感染。',2,'context'),q('What is pseudoscience?','a claim presented as science without sound evidence or testable methods','a scientific claim repeatedly confirmed in controlled trials','a false name used by a novelist','伪科学看似科学，却缺乏可靠证据或可检验方法。',1,'meaning'),q('What does pseudo- contribute to pseudoscience?','the meaning “false” or “pretended”','the meaning “mind”','the meaning “public”','pseudo- 表示“假”或“伪”。',1,'word-formation')]);
P('psyche','Psyche comes from Greek psychē, “breath, life, or soul,” and in English refers to the mind or inner emotional life of a person or group.',C('psyche.s1','心灵；精神世界','After months of displacement, the counselor asked how the repeated alarms had affected the residents’ psyche.','居民流离失所数月后，咨询师询问反复响起的警报对他们的心理造成了什么影响。','The counselor asked / how repeated alarms had affected / the residents’ psyche.','psyche 指人的内在心理、情感或精神世界。','咨询师关注的是警报带来的心理影响，不是身体损伤。'),M('The survey measured each resident’s psyche in centimeters with a tape measure around the waist.','The survey explored each resident’s psyche through questions about feelings, fears, and memories.','psyche 是心灵或心理世界，不能用腰围厘米数直接测量。','meaning'),[q('What effect did the counselor ask about?','the alarms’ effect on residents’ inner mental and emotional life','the length of the residents’ waistlines','the power needed to run the alarm system','咨询师询问警报对居民心理的影响。'),q('What does psyche mean?','the mind or inner emotional life','a medical doctor who treats mental illness','the written authority to vote for someone','psyche 指心灵或内在精神世界。',1,'meaning'),q('Which question explores a character’s psyche?','What fear continues to shape her choices?','How many centimeters long is the door?','Which publisher printed the book?','询问持续影响选择的恐惧是在探索人物心理。',1,'context'),q('Which Greek form is the source of psyche?','psychē, “breath, life, or soul”','pseudēs, “false”','pólis, “city”','psyche 来自表示呼吸、生命或灵魂的希腊语 psychē。',1,'word-formation')]);
P('psychiatric','Psychiatric derives from psychiatry, ultimately from Greek psychē “mind” and iatreia “healing”; it means relating to the medical treatment of mental disorders.',C('psychiatric.s1','精神科的；精神病学的','The hospital opened a psychiatric clinic where patients could receive assessment and follow-up care.','医院开设了一所精神科诊所，患者可在那里接受评估和后续照护。','The hospital opened a psychiatric clinic / where patients could receive / assessment and follow-up care.','psychiatric 描述与精神疾病的医学评估或治疗有关的事物。','诊所提供精神科评估与后续医疗。'),M('The hospital opened a psychiatic clinic for mental-health assessment and follow-up care.','The hospital opened a psychiatric clinic for mental-health assessment and follow-up care.','单词拼写遗漏了第二个 r，标准拼法为 psychiatric。','spelling'),[q('What care did the new psychiatric clinic offer?','medical assessment and follow-up care','a public voting proxy','treatment for a broken bicycle tire','精神科诊所提供医学评估和后续照护。'),q('What does psychiatric describe?','connected with medical care for mental disorders','concerned with printing books for the public','related to a pupa becoming an adult insect','psychiatric 指与精神疾病医疗有关的。',1,'meaning'),q('Which phrase uses psychiatric correctly?','psychiatric evaluation by a trained medical team','psychiatric rainfall measured at the weather station','psychiatric proxy server for student devices','由专业医疗团队进行的精神科评估搭配自然。',1,'collocation'),q('Which spelling is standard?','psychiatric','psychiatic','psycheatric','标准拼写是 psychiatric。',1,'spelling')]);
P('psychiatrist','Psychiatrist is formed from psychiatry and the agent suffix -ist; it names a medical doctor trained to diagnose and treat mental disorders.',C('psychiatrist.s1','精神科医生','The psychiatrist reviewed Luis’s symptoms, discussed treatment choices, and arranged a follow-up appointment.','精神科医生评估了路易斯的症状，讨论治疗选择，并安排了复诊。','The psychiatrist reviewed symptoms / discussed treatment choices / and arranged follow-up care.','psychiatrist 指受过医学训练、诊断和治疗精神障碍的医生。','症状评估、治疗方案和复诊都属于医疗照护。'),M('Mara visited a psychiatrist to have a fractured wrist set and fitted with a cast.','Mara visited an orthopedist to have her fractured wrist set and fitted with a cast.','骨折复位属于骨科治疗；精神科医生负责精神障碍的诊断和治疗。','word-choice'),[q('What did the psychiatrist arrange for Luis?','a follow-up appointment about his treatment','a book contract under a pseudonym','a proxy server for a hospital computer','精神科医生安排了治疗后的复诊。'),q('Who is a psychiatrist?','a medical doctor trained to treat mental disorders','a publisher specializing in psychology textbooks','a technician who installs a proxy server','精神科医生是受过精神障碍医疗训练的医生。',1,'meaning'),q('Which patient is seeing a psychiatrist for an appropriate reason?','a patient seeking medical care for recurring panic attacks','a patient needing a broken wrist set','a patient asking who published a novel','反复惊恐发作需要精神科医疗评估。',1,'context'),q('How is psychiatrist formed?','psychiatry + -ist, a person specializing in the field','psyche + -like, meaning a printed book','public + -ist, meaning a government office','psychiatrist 由 psychiatry 加表示从业者的 -ist 构成。',1,'word-formation')]);
P('psychiatry','Psychiatry combines Greek psychē “mind” with iatreia “healing”; it is the medical field concerned with mental disorders and their clinical treatment.',[C('psychiatry.s1','精神病学','The medical school added a psychiatry course on diagnosis, medication, and the history of mental-health care.','医学院新增了一门精神病学课程，内容包括诊断、药物和精神卫生医疗史。','The medical school added a psychiatry course / on diagnosis and medication / and care history.','psychiatry.s1 指研究和治疗精神障碍的医学学科。','课程覆盖诊断、药物和精神卫生医疗。'),C('psychiatry.s2','精神科医疗；精神病治疗','After a primary-care referral, the patient received psychiatry through a clinic that provided regular medical appointments.','经基层医疗转介后，患者在诊所接受定期精神科医疗。','The patient received psychiatry / through a clinic / with regular medical appointments.','psychiatry.s2 可指医生提供的精神科诊疗服务。','定期预约体现临床诊疗，而不只是学科研究。')],M('The hospital described psychiatry as a branch of botany that identifies plants by the shape of their leaves.','The hospital described psychiatry as the medical field that assesses and treats mental disorders.','识别植物属于植物学；psychiatry 是精神障碍的医学研究和治疗。','meaning'),[q('What topics were included in the medical school’s psychiatry course?','diagnosis, medication, and mental-health care history','how to issue a voting proxy','how to turn fruit into prune snacks','课程介绍精神障碍诊断、药物和医疗史。',1,'context'),q('What did the patient receive after referral?','regular clinical mental-health appointments','a degree in plant identification','a published novel under a pen name','患者接受了定期精神科诊疗。',2,'context'),q('What field is psychiatry?','the medical study and treatment of mental disorders','the scientific study of how language is processed','the craft of operating puppets','psychiatry 是研究和治疗精神障碍的医学领域。',1,'meaning'),q('Which Greek elements contribute to psychiatry?','psychē “mind” + iatreia “healing”','pseudo “false” + science','pólis “city” + logos “law”','psychiatry 结合了“心灵”和“治疗”的希腊语词。',1,'word-formation')]);
P('psychoanalysis','Psychoanalysis combines psycho- “mind” with analysis; the term was introduced in Freud’s work for a clinical method examining unconscious mental processes.',C('psychoanalysis.s1','心理分析；精神分析','In the seminar, students read a case history to see how psychoanalysis interprets recurring dreams and free associations.','研讨课上，学生阅读病例，了解心理分析如何解释反复出现的梦和自由联想。','Students read a case history / to see how psychoanalysis interprets / dreams and free associations.','psychoanalysis 指通过解释无意识过程来理解心理的临床理论与方法。','梦和自由联想被作为心理分析材料来讨论。'),M('The textbook called psychoanalysis a blood test that measures the amount of oxygen in a patient’s veins.','The textbook called psychoanalysis a clinical method that interprets unconscious processes through material such as dreams and free association.','血液含氧检测是实验室检验，不是心理分析方法。','meaning'),[q('What materials did the seminar discuss?','recurring dreams and free associations','the shape of a pupa and its wings','publicity for a new book','研讨课讨论梦和自由联想如何用于心理分析。'),q('What does psychoanalysis examine?','unconscious mental processes','the pressure inside a bicycle tire','the voting authority in a proxy form','psychoanalysis 用于探究无意识心理过程。',1,'meaning'),q('Which activity best fits a psychoanalytic case discussion?','considering recurring dreams alongside a patient’s associations','measuring blood oxygen with a laboratory sensor','counting the pages in a published novel','分析反复梦境和联想符合心理分析讨论。',1,'context'),q('What does psycho- contribute to psychoanalysis?','a connection with the mind','a connection with public government','a connection with dried fruit','psycho- 表示与心灵或心理有关。',1,'word-formation')]);
P('psychoanalyst','Psychoanalyst is formed from psychoanalysis and -ist; it refers to a practitioner trained in psychoanalytic theory and technique.',C('psychoanalyst.s1','心理分析学家；精神分析师','The psychoanalyst invited the client to speak freely while keeping track of recurring themes in the conversation.','心理分析师请来访者自由表达，同时留意谈话中反复出现的主题。','The psychoanalyst invited the client / to speak freely / while noting recurring themes.','psychoanalyst 指受过精神分析理论与技术训练的从业者。','来访者自由表达、分析师留意反复主题，符合此方法。'),M('The psychoanalyst treated a broken leg by setting the bone and applying a cast in the emergency room.','The orthopedist treated the broken leg; the psychoanalyst discussed the client’s recurring dreams.','骨折复位属于骨科治疗，不是精神分析师的工作。','word-choice'),[q('What did the psychoanalyst invite the client to do?','speak freely while recurring themes were noted','sign a proxy to vote at a meeting','publish the conversation under a pseudonym','来访者被邀请自由表达，分析师观察反复主题。'),q('What is a psychoanalyst trained to use?','psychoanalytic theory and technique','a pulley system for lifting patients','methods for diagnosing broken bones','心理分析师受训使用精神分析理论与技术。',1,'meaning'),q('Which activity fits the psychoanalyst’s role?','discussing a client’s recurring dreams and associations','setting a fractured leg in an emergency room','installing a network proxy for a clinic','讨论梦境与联想符合精神分析师的工作。',1,'context'),q('Which suffix identifies the practitioner in psychoanalyst?','-ist','-ness','-ly','-ist 表示从事某领域的人。',1,'word-formation')]);
P('psychodynamic','Psychodynamic combines psycho- “mind” with dynamic, ultimately Greek dynamikos “powerful”; it concerns how unconscious drives and early relationships influence behavior.',C('psychodynamic.s1','心理动力的','A psychodynamic account connected the character’s fear of abandonment with patterns established in early relationships.','一种心理动力学解释把人物的被遗弃恐惧与早期关系中形成的模式联系起来。','A psychodynamic account connected the fear / with patterns / established in early relationships.','psychodynamic 指关注无意识动力及其对行为影响的理论取向。','解释把当前恐惧联系到早期关系模式。'),M('The article called its explanation psychodynamic but based it only on the weather and ignored motives or relationships.','The article offered a psychodynamic explanation by examining unconscious motives and early relationships.','只讨论天气、不涉及心理动力或关系的解释不属于心理动力学解释。','meaning'),[q('What did the psychodynamic account connect to the character’s fear?','patterns in early relationships','a public vote at a shareholder meeting','a chemical change in a beaker','例句将恐惧与早期关系模式相联系。'),q('What does psychodynamic emphasize?','the influence of unconscious drives and relationships on behavior','the use of punctuation marks in a text','the study of public health across a town','心理动力学关注无意识动力和关系对行为的影响。',1,'meaning'),q('Which question is psychodynamic in focus?','How might early attachment shape her current reactions?','How many pages did the publisher print?','Which route carries network traffic?','探问早期依恋如何影响当下反应，符合心理动力视角。',1,'context'),q('What does dynamic contribute to psychodynamic?','the idea of forces or drives shaping change','the idea of a false name','the idea of a dried plum','dynamic 带有力量或驱动力的含义。',1,'word-formation')]);
P('psycholinguistics','Psycholinguistics is a compound of psychology and linguistics; it studies the mental processes involved in understanding, producing, and learning language.',C('psycholinguistics.s1','心理语言学','The psycholinguistics lab compared how bilingual volunteers recognized spoken words in each of their languages.','心理语言学实验室比较双语志愿者识别两种语言口语词汇的方式。','The psycholinguistics lab compared / how bilingual volunteers recognized / spoken words in both languages.','psycholinguistics 研究语言理解、产生或习得所涉及的心理过程。','实验考察志愿者如何在两种语言中识别口语词。'),M('The report called the excavation of ancient pottery psycholinguistics because it did not examine language or mental processing.','The report called the study of bilingual word recognition psycholinguistics because it examined language processing in the mind.','只挖掘陶器、不研究语言或心理过程，不属于心理语言学。','meaning'),[q('What did the lab compare?','bilingual volunteers’ recognition of spoken words','how a town stores emergency water','which author used a pseudonym','实验比较双语者识别口语词的方式。'),q('What does psycholinguistics study?','mental processes involved in language','medical treatment of mental disorders','the technique of moving a puppet','心理语言学研究语言相关的心理过程。',1,'meaning'),q('Which project belongs to psycholinguistics?','tracking how children learn to recognize new words','measuring the mineral content of pumice','editing repeated paragraphs out of a report','研究儿童如何学会识别新词属于心理语言学。',1,'context'),q('Which two fields form psycholinguistics?','psychology and linguistics','psychiatry and publication','pseudoscience and public health','psycholinguistics 结合 psychology 与 linguistics。',1,'word-formation')]);
P('psychological','Psychological comes from psychology, ultimately Greek psychē “mind” and -logia “study”; it means relating to the mind, mental processes, or psychology.',C('psychological.s1','心理的；心理学的','The evacuation plan addressed psychological stress as well as the physical risks of the storm.','疏散计划既考虑风暴造成的身体风险，也考虑心理压力。','The plan addressed psychological stress / as well as / the storm’s physical risks.','psychological 指与心理状态或心理学有关的。','计划将心理压力与身体风险分别纳入考虑。'),M('The report called broken windows a psychological risk because the damage existed only in residents’ thoughts and not in the building.','The report called anxiety a psychological risk and broken windows a physical risk.','焦虑属于心理风险，窗户破损是物理风险。','meaning'),[q('Which kind of risk did the plan consider besides physical danger?','psychological stress','the cost of a publisher’s printing press','the shape of a pupa','计划还考虑风暴造成的心理压力。'),q('What does psychological mean?','relating to the mind or mental processes','relating to a written proxy','relating to public buildings only','psychological 指与心灵或心理过程有关。',1,'meaning'),q('Which is a psychological effect of displacement?','persistent anxiety after losing one’s home','a puncture in a bicycle tire','a new edition of a book','失去住所后持续焦虑是心理影响。',1,'context'),q('Which noun is psychological derived from?','psychology','psychiatrist','pseudonym','psychological 来自 psychology。',1,'word-formation')]);
P('psychologically','Psychologically is the adverb from psychological; it means with regard to a person’s mental state, motives, or emotional effects.',C('psychologically.s1','心理上；从心理角度','The coach prepared the injured runner psychologically for a gradual return to competition.','教练从心理上帮助受伤的跑者为逐步重返比赛做好准备。','The coach prepared the runner psychologically / for a gradual return / to competition.','psychologically 修饰动作，说明准备或影响发生在心理层面。','这里强调帮助运动员做好心理准备。'),M('The coach prepared the runner psychologically by fitting a new brace onto the injured ankle.','The coach prepared the runner physically with a brace and psychologically by discussing the return to competition.','给脚踝戴支具是身体层面的准备；心理准备包括应对复赛的情绪和信心。','meaning'),[q('What was the runner being prepared for psychologically?','a gradual return to competition','a public vote at a shareholder meeting','a new publisher’s contract','教练帮助跑者从心理上准备重返赛场。'),q('What does psychologically mean?','with regard to the mind or emotional state','by using a pulley to lift an object','in a way that makes a book public','psychologically 指从心理或情绪层面。',1,'meaning'),q('Which sentence uses psychologically correctly?','The sudden move affected the child psychologically.','The editor psychologically removed two paragraphs from the report.','The team paid the insurance premium psychologically.','搬家影响孩子的心理状态，副词用法恰当。',1,'grammar'),q('Which adjective is psychologically built from?','psychological','psycholinguistics','psychiatrist','psychologically 是由形容词 psychological 加 -ly 构成。',1,'word-formation')]);
P('psychologist','Psychologist combines psychology and -ist; it can mean a researcher who studies the mind or a trained professional who provides psychological help.',[C('psychologist.s1','心理学家（研究者）','The psychologist ran an experiment to test how background noise affected volunteers’ memory.','这位心理学家开展实验，测试背景噪声如何影响志愿者的记忆。','The psychologist ran an experiment / to test how noise affected / volunteers’ memory.','psychologist.s1 指研究心理和行为的科学工作者。','研究者通过实验测试噪声和记忆的关系。'),C('psychologist.s2','心理咨询师；心理服务专业人员','A psychologist helped the student develop coping strategies for exam anxiety during weekly appointments.','心理服务专业人员通过每周会谈帮助学生制定应对考试焦虑的策略。','A psychologist helped the student / develop coping strategies / during weekly appointments.','psychologist.s2 可指接受专业训练、提供心理帮助的从业者。','每周会谈帮助学生处理焦虑。')],M('The psychologist operated on the student’s fractured knee during a research appointment about memory.','The orthopedic surgeon treated the knee; the psychologist studied memory and helped with exam anxiety.','骨科手术不是心理学家的工作；心理学家研究心理或提供心理帮助。','word-choice'),[q('What did the research psychologist test?','the effect of background noise on memory','how to set a fractured knee','how to filter student websites with a proxy','实验研究噪声对记忆的影响。',1,'context'),q('How did the second psychologist help the student?','by developing coping strategies for exam anxiety','by operating on a knee injury','by publishing the student’s exam results','心理服务人员帮助学生制定应对焦虑的策略。',2,'context'),q('Which person is a psychologist in the research sense?','a scientist studying how attention changes with sleep','a publisher producing a psychology textbook','a doctor treating a broken ankle with surgery','研究注意力与睡眠关系的科学家是心理学家。',1,'meaning'),q('What field does a psychologist specialize in?','psychology','public affairs','pseudoscience','psychologist 从事心理学研究或相关专业服务。',1,'word-formation')]);
P('psychology','Psychology derives from Greek psychē “mind or soul” and -logia “study”; it means the scientific study of mind and behavior, or a characteristic way of thinking.',[C('psychology.s1','心理学','The psychology course taught students how experiments test memory, attention, and decision-making.','心理学课程教学生了解实验如何检验记忆、注意力和决策。','The psychology course taught / how experiments test / memory and decision-making.','psychology.s1 指研究心智和行为的科学学科。','课程以实验研究认知能力和决策行为。'),C('psychology.s2','心理；心态；心理特点','The psychology of the team changed after the captain admitted the mistake and restored trust.','队长承认错误并重建信任后，球队的心态发生了变化。','The psychology of the team changed / after the captain admitted the mistake / and restored trust.','psychology.s2 指个人或群体特有的思维、感受或行为方式。','例句描述团队信任恢复后的群体心态变化。')],M('The psychology of the team changed when the players’ attention and trust stayed exactly the same after the apology.','The psychology of the team changed when the apology rebuilt trust and altered how the players approached the next match.','道歉重建信任、改变团队态度才体现群体心理变化。','meaning'),[q('What did students learn in the psychology course?','how experiments test memory, attention, and decisions','how to sign a proxy before a shareholder vote','how to publish a novel under a pen name','心理学课程介绍认知实验。',1,'context'),q('What changed after the captain admitted the mistake?','the team’s shared outlook and trust','the laboratory’s water supply','the printed punctuation in a report','这里 psychology 指球队的群体心态。',2,'context'),q('Which is the scientific meaning of psychology?','the study of mind and behavior','the study of how to trim a rosebush','the practice of acting under another person’s name','心理学是对心智和行为的科学研究。',1,'meaning'),q('Which Greek elements are reflected in psychology?','psychē “mind” + -logia “study”','pseudo “false” + onyma “name”','pólis “city” + dynamis “force”','psychology 由表示心灵与研究的希腊语词素构成。',1,'word-formation')]);
P('psychosomatic','Psychosomatic combines Greek psychē “mind” with sōma “body”; it describes physical symptoms caused or aggravated by psychological factors.',C('psychosomatic.s1','心身性的；由心理因素引起或加重的','The doctor explained that stress could worsen the patient’s psychosomatic stomach pain even though the pain was physically real.','医生解释说，尽管疼痛确实存在，压力仍可能加重患者由心理因素引发的胃痛。','Stress could worsen the patient’s psychosomatic pain / even though / the pain was physically real.','psychosomatic 描述心理因素引发或加重的身体症状，并不表示症状是装出来的。','压力与胃痛加重有关，医生仍承认疼痛真实存在。'),M('The doctor called the pain psychosomatic because the patient was pretending and no pain was actually felt.','The doctor called the pain psychosomatic because psychological stress contributed to real physical symptoms.','心身性症状是真实身体症状，可能受心理因素影响，不等于假装生病。','meaning'),[q('What did the doctor say about the patient’s stomach pain?','stress could worsen real physical pain','the patient was pretending to feel pain','the pain had no connection to the body','医生说明压力可能加重真实的身体疼痛。'),q('What does psychosomatic describe?','a physical symptom influenced by psychological factors','a mental state measured by a thermometer','a disease caused only by a broken bone','psychosomatic 指受心理因素影响的身体症状。',1,'meaning'),q('Which case may be psychosomatic?','stress worsens a person’s real headaches despite no new injury','a snapped bone hurts only when touched','a made-up symptom the patient admits is false','压力加重真实头痛可能属于心身性症状。',1,'context'),q('Which Greek roots contribute to psychosomatic?','psychē “mind” + sōma “body”','pseudo “false” + onyma “name”','pólis “city” + logos “study”','psychosomatic 由表示心灵和身体的希腊语词素构成。',1,'word-formation')]);
P('ptarmigan','Ptarmigan comes from Scottish Gaelic tàrmachan, the name of the bird; the silent initial p was added in English spelling, probably through mistaken association with Greek pteron “wing.”',C('ptarmigan.s1','雷鸟','The ptarmigan’s mottled summer feathers blended with the rocky tundra, while its winter plumage turned white against the snow.','雷鸟夏季斑驳的羽毛与岩石苔原融为一体，冬季羽毛则变白，与雪地相衬。','The ptarmigan’s summer feathers blended with the tundra / while its winter plumage / turned white.','ptarmigan 是生活在北极或高山地区、会季节性换羽的松鸡类鸟。','同一只鸟的羽色会随季节改变。'),M('The field guide identified the ptarmigan by its bright green tropical feathers that stayed unchanged throughout the year.','The field guide identified the ptarmigan by its mottled summer plumage and white winter feathers.','ptarmigan 的羽色会季节变化，并不全年保持亮绿色。','meaning'),[q('How did the ptarmigan’s appearance change in winter?','its plumage turned white','its feathers became bright green','it grew a long tropical tail','例句指出雷鸟冬季羽毛变白。'),q('Which bird is a ptarmigan?','a grouse of arctic or alpine regions that changes plumage by season','a tropical parrot with a fixed green coat','a Mesozoic reptile that flew with membranous wings','ptarmigan 是北极或高山地区会季节换羽的松鸡类鸟。',1,'meaning'),q('Why was the bird hard to see on the summer tundra?','its mottled feathers blended with the rocky ground','it hid under a snow-white wing','its name was printed in silent letters','斑驳羽色与岩石苔原融为一体。',1,'context'),q('What likely influenced the added silent p in ptarmigan?','a mistaken link to Greek pteron, “wing”','the Latin word for a plum','the suffix that means “small”','拼写中的无声 p 可能受希腊语“翼”一词影响。',1,'word-formation')]);
P('pterosaur','Pterosaur is formed from Greek pteron “wing” and sauros “lizard”; it names a flying reptile of the Mesozoic, distinct from both dinosaurs and birds.',C('pterosaur.s1','翼龙','The museum’s pterosaur model showed a membrane stretched between its elongated finger and body, not a bird’s feathered wing.','博物馆的翼龙模型显示，翼膜连在伸长的手指与身体之间，而不是鸟类的羽毛翅膀。','The pterosaur model showed a membrane / stretched between its finger / and its body.','pterosaur 指中生代会飞的爬行动物，不是恐龙或鸟类。','模型展示的是翼龙的翼膜结构。'),M('The guide classified the pterosaur as a modern bird because its wings were covered in feathers and it lived today.','The guide classified the pterosaur as an extinct flying reptile with a wing membrane.','翼龙是已灭绝的爬行动物，其翼结构不同于现代鸟类羽翼。','meaning'),[q('What supported the pterosaur’s wing in the model?','a membrane stretched from an elongated finger to the body','a broad fan of modern flight feathers','a featherless arm of a living mammal','模型展示了从伸长手指连到身体的翼膜。'),q('What kind of animal was a pterosaur?','an extinct flying reptile','a modern bird','a Mesozoic swimming mammal','翼龙是中生代的飞行爬行动物。',1,'meaning'),q('Which claim about pterosaurs is accurate?','they were flying reptiles, not dinosaurs or birds','they were modern birds with feathered wings','they were mammals that lived after humans','翼龙属于飞行爬行动物，既不是恐龙也不是鸟。',1,'meaning'),q('What do the Greek parts of pterosaur mean?','pteron “wing” + sauros “lizard”','psyche “mind” + soma “body”','pseudo “false” + science','pterosaur 由希腊语“翼”和“蜥蜴”构成。',1,'word-formation')]);
P('pub','Pub is a shortening of public house, a British term for a place licensed to sell alcoholic drinks; it can also refer to the social custom of meeting there.',[C('pub.s1','酒馆；酒吧','The village pub serves meals at noon and closes its garden patio when the weather turns cold.','村里的酒馆中午供应餐食，天气转冷时会关闭花园露台。','The village pub serves meals / at noon / and closes its garden patio in cold weather.','pub.s1 指供应酒类、常兼供餐食的酒馆或酒吧。','村庄酒馆供应餐食并有露台。'),C('pub.s2','酒吧社交；去酒吧聚会','After the match, the players went for a pub with their neighbors, sharing stories rather than watching another game.','比赛结束后，球员和邻居去酒吧聚会，大家讲故事而不是再看一场比赛。','After the match / the players went for a pub / with their neighbors.','pub.s2 可指去酒吧相聚这一社交活动或习惯。','比赛后与邻居相聚体现酒吧社交。')],M('The village pub served only library books and did not function as a place for drinks, food, or socializing.','The village pub served drinks and meals and offered a place for neighbors to meet.','pub 是可供饮酒、用餐或社交的酒馆，不是图书馆。','meaning'),[q('What did the village pub serve at noon?','meals','only library books','train tickets','村里的酒馆中午供应餐食。',1,'context'),q('What did the players do after the match?','met neighbors at a pub and shared stories','played another match at the library','signed a proxy for a shareholder vote','他们去酒吧与邻居交谈。',2,'context'),q('Which sentence uses pub for the social custom?','They went for a pub after work and talked with friends.','The pub has a tiled roof and a garden patio.','The publisher released a new edition.','下班后去酒吧与朋友聚会，是 pub 的社交活动义。',2,'meaning'),q('What phrase is pub shortened from?','public house','public health','published house','pub 是 public house 的缩略说法。',1,'word-formation')]);
P('public','Public comes through Old French from Latin publicus, “of the people”; it describes shared or government-related things, something open or known to others, and people generally.',[C('public.s1','公共的；公众可使用的','Residents may use the public reading room without paying a membership fee.','居民无需缴纳会员费即可使用这间公共阅览室。','Residents may use the public reading room / without paying / a membership fee.','public.s1 指面向公众、供公众使用或与普通人有关的。','阅览室向居民开放，不需会员资格。'),C('public.s2','公开的；当众的','The mayor made a public apology in the town square rather than sending a private letter.','市长在镇广场公开道歉，而不是寄一封私人信件。','The mayor made a public apology / in the town square / rather than sending a private letter.','public.s2 指为许多人所知或在众人面前进行的。','道歉在广场当众作出。'),C('public.s3','政府的；公营的','The city used public funds to repair the bridge and publish a detailed spending report.','市政府使用公共资金维修桥梁，并公布了详细支出报告。','The city used public funds / to repair the bridge / and report the spending.','public.s3 指由政府提供、管理或出资的。','维修资金由市政府支出。'),C('public.s4','公众；民众','The public asked the council to explain why the water restrictions would last another month.','公众要求市议会解释为何限水措施还要持续一个月。','The public asked the council / to explain why / restrictions would continue.','public.s4 作名词，表示普通公众或民众。','民众向议会提出解释要求。')],M('The mayor made a public apology in a locked private room and ensured nobody outside the room could hear it.','The mayor made a public apology in the town square where residents could hear it.','公开道歉是让公众能够看到或听到的，不是秘密关门进行。','meaning'),[q('Who could use the reading room without membership?','residents','only city employees with a paid card','one appointed proxy','阅览室供居民使用且无需缴纳会员费。',1,'context'),q('Where did the mayor make the public apology?','in the town square before residents','in a locked room with no listeners','inside the bridge’s support beam','市长在镇广场当众道歉。',2,'context'),q('What paid for the bridge repair?','government funds','the mayor’s private letter','the reading room’s membership fees','桥梁维修使用的是公共资金。',3,'context'),q('In “The public asked the council,” what is public?','people in general','a government-funded bridge','an apology made in the square','这里 public 作名词，指公众民众。',4,'grammar')]);
P('public affairs','Public affairs combines public “concerning people or government” with affairs “matters”; it refers to issues involving the community, government, or public life.',C('public affairs.s1','公共事务','The civic group holds monthly forums on public affairs, including housing policy and access to clean water.','公民团体每月举办公共事务论坛，讨论住房政策和清洁水获取等议题。','The group holds forums on public affairs / including housing policy / and clean-water access.','public affairs 指涉及公众、政府或公共生活的事务。','住房政策和清洁水供应是社区公共议题。'),M('The forum described one family’s private breakfast menu as public affairs even though it had no community or government relevance.','The forum discussed housing policy and clean-water access as public affairs because they affect the community.','与社区或政府无关的私人早餐菜单不属于公共事务。','meaning'),[q('Which topics did the civic group discuss?','housing policy and clean-water access','the private menu of one family','the repair instructions for a bicycle tire','论坛讨论住房政策和清洁水获取。'),q('What are public affairs?','matters involving the community, government, or public life','private details that concern no one else','the routine duties of a book publisher','公共事务涉及社区、政府或公共生活。',1,'meaning'),q('Which issue belongs on a public-affairs forum?','how the city allocates funds for local schools','what one resident ate for breakfast','which color to paint a private bedroom','市政府如何分配学校经费属于公共议题。',1,'context'),q('Why are housing policy and water access public affairs?','they affect community life and public decisions','they are secret medical facts','they describe the anatomy of a flying reptile','住房和供水影响社区生活及公共决策。',1,'context')]);
P('public health','Public health combines public “the population” with health; it is the organized protection and improvement of health across communities.',C('public health.s1','公共卫生','The public health team mapped vaccination rates by district and arranged mobile clinics for underserved neighborhoods.','公共卫生团队按区域绘制疫苗接种率地图，并为服务不足的社区安排流动诊所。','The public health team mapped rates / and arranged mobile clinics / for underserved neighborhoods.','public health 指保护和改善整个人群健康的组织性工作。','团队依据地区数据配置流动诊所，服务社区健康。'),M('The report called one patient’s private hairstyle public health because it affected no one else and required no community action.','The report treated vaccination access across districts as a public-health issue affecting community well-being.','单个病人的私人发型不涉及人群健康或社区行动。','meaning'),[q('What did the public health team map?','vaccination rates in each district','the publisher’s monthly book sales','the wing shape of a pterosaur','团队按区域绘制疫苗接种率。'),q('What is public health concerned with?','protecting and improving health across a population','providing one person with a private pen name','repairing public reading-room furniture','公共卫生关注整个人群的健康保护与改善。',1,'meaning'),q('Which action is public health work?','organizing mobile clinics in neighborhoods with low vaccine access','choosing a private family’s dinner menu','installing a proxy server for a book publisher','为疫苗服务不足的社区安排流动诊所属于公共卫生工作。',1,'context'),q('Why did the team map rates by district?','to identify where community health services were needed','to decide which district had the best pub patio','to publish a novel under a pseudonym','分区数据帮助判断哪些社区需要医疗服务。',1,'context')]);
P('publican','Publican comes from Latin publicanus, a Roman tax collector; in modern British English it can mean the owner or manager of a pub.',[C('publican.s1','酒馆老板；古罗马税吏','The publican greeted regular customers at the inn, while a history text used the same word for a Roman tax collector.','酒馆老板在旅店迎接熟客；一本历史教材也用同一个词指古罗马税吏。','The publican greeted regulars / at the inn / while the history text described a Roman tax collector.','publican.s1 可指英国酒馆老板或经营者，也可指古罗马的税吏。','例句呈现现代酒馆义和历史上的税吏义。')],M('The publican managed a British pub but the story claimed he was a Roman tax collector who lived two thousand years earlier.','The publican ran a British pub; in an ancient Roman setting, a publican could collect taxes.','现代酒馆经营者和古罗马税吏是该词的不同语境义，不应混为一个人的身份。','meaning'),[q('What did the publican do at the inn?','greeted regular customers','managed the city’s public-health map','signed a proxy to vote for a shareholder','酒馆老板在旅店迎接熟客。'),q('What could a publican do in ancient Rome?','collect taxes','publish a novel under a pen name','treat mental disorders as a psychiatrist','古罗马的 publican 可以是税吏。',1,'context'),q('Which person is a modern British publican?','the person who owns or runs a local pub','a researcher studying language processing','a government official repairing a public bridge','现代英国的 publican 是酒馆老板或经营者。',1,'meaning'),q('Which Latin word is publican derived from?','publicanus, a Roman tax collector','psychē, the mind','prunum, a plum','publican 源自表示罗马税吏的 publicanus。',1,'word-formation')]);
P('publication','Publication comes from Latin publicatio, from publicare “make public”; it can mean a printed work or the act of making information available.',C('publication.s1','出版物；出版；发表','The journal delayed publication until an independent review verified the tables and corrected the author’s references.','期刊推迟了发表时间，直到独立审查核实表格并更正作者的参考文献。','The journal delayed publication / until an independent review / verified the tables and references.','publication.s1 可指出版或发表这一行为，也可指出版物。','例句中的 publication 指研究内容正式发表的过程。'),M('The journal called its publisher a publication because the company itself was the printed article released to readers.','The journal called the article a publication and named the company that issued it the publisher.','publication 是作品或发表行为；负责发行作品的个人或公司是 publisher。','word-choice'),[q('Why did the journal delay publication?','it was waiting for an independent review of tables and references','it had already finished checking every source','the publisher had changed the article into a publican','期刊等待独立审查核实表格和参考文献。'),q('What can publication refer to?','a printed work or the act of making it available','the company or person that issues a book only','a person who collects Roman taxes only','publication 可指出版物或发表这一行为。',1,'meaning'),q('Which sentence uses publication for a work?','The library added the quarterly publication to its shelves.','Publication was delayed until the editor checked the citations.','They voted by proxy at the meeting.','图书馆把季刊放上书架，这里 publication 指出版物。',1,'grammar'),q('Which related noun names the company that issues a work?','publisher','publication','publicity','publisher 指出版或发行作品的个人或公司。',1,'word-formation')]);
P('publicity','Publicity is formed from public and -ity; it means public attention or information intended to make people notice a person, event, or product.',C('publicity.s1','公众关注；宣传','The small theater gained publicity when a national radio program reviewed its new production.','一家全国性广播节目评论小剧场的新剧后，这家剧院获得了公众关注。','The theater gained publicity / when a national radio program / reviewed its new production.','publicity 指公众或媒体关注，也可指使公众注意某事的宣传。','广播评论让更多听众知道了剧院的新剧。'),M('The play received wide publicity even though no media outlet mentioned it and nobody outside the cast knew it existed.','The play received wide publicity after several media outlets reviewed it and audiences began discussing it.','没有媒体提及、公众不知情，就谈不上广泛关注或宣传。','meaning'),[q('What brought publicity to the theater?','a national radio review of its production','a private note that nobody read','a Roman tax record kept in an archive','全国广播节目评论带来了公众关注。'),q('What does publicity mean?','public attention or promotion that makes people notice something','a printed work or the act of printing it','a medical field treating mental disorders','publicity 指公众关注或宣传。',1,'meaning'),q('Which event would likely generate publicity for a new museum?','a widely shared newspaper feature about its opening','a confidential memo filed and never released','a printer running out of paper in a closed office','广泛传播的开馆报道会带来宣传关注。',1,'context'),q('Which suffix appears in publicity?','-ity, forming a noun from public','-ist, naming a medical specialist','-ly, forming an adverb','publicity 由 public 加名词后缀 -ity 构成。',1,'word-formation')]);
P('publicize','Publicize combines public with -ize; it means to make information, an event, or a product widely known.',C('publicize.s1','宣传；公布','The council will publicize the new recycling schedule through local radio, posters, and its website.','市议会将通过地方广播、海报和网站宣传新的回收时间表。','The council will publicize the schedule / through radio, posters / and its website.','publicize 指主动让公众知道某事，常通过传播信息或宣传。','市议会使用多种渠道公布时间表。'),M('The council publicized the recycling schedule by keeping it secret from residents and removing all public notices.','The council publicized the recycling schedule by posting notices and sharing it on local radio.','把信息保密并撤下通知会阻止公众得知，而不是宣传。','meaning'),[q('How will the council publicize the schedule?','through radio, posters, and its website','by hiding it from residents','by filing it in a private drawer only','市议会通过广播、海报和网站宣传时间表。'),q('What does publicize mean?','make something widely known','remove unnecessary branches from a tree','treat a patient for mental illness','publicize 指让公众广泛知道某事。',1,'meaning'),q('Which action publicizes a safety notice?','sharing it on the town website and at bus stops','keeping it in a sealed office file','telling only the person who wrote it','在网站和公交站发布通知让公众知晓，属于宣传公布。',1,'context'),q('Which word is publicize formed from?','public + -ize','pupil + -ize','pseudonym + -ize','publicize 由 public 加动词后缀 -ize 构成。',1,'word-formation')]);
P('publicly','Publicly is public plus -ly; it means openly or in a way that can be seen or known by people, and sometimes on behalf of the public.',C('publicly.s1','公开地；公然地','The mayor publicly apologized at the council meeting and answered questions from residents.','市长在议会会议上公开道歉，并回答了居民的问题。','The mayor publicly apologized / at the council meeting / and answered residents’ questions.','publicly 是副词，修饰动作，表示公开地或当众地。','道歉在居民可见可闻的会议上进行。'),M('The mayor publicly apologized by sending a sealed letter that no resident or reporter was allowed to read.','The mayor publicly apologized by speaking at an open meeting attended by residents and reporters.','无人能读的密封信是私人道歉，不是公开道歉。','meaning'),[q('Where did the mayor publicly apologize?','at the council meeting before residents','in a sealed room with no audience','through an unsigned note kept private','市长在议会会议上当众道歉。'),q('What does publicly mean?','openly or where people can see or know','with careful mental preparation','by using a tool to pry something open','publicly 指公开地、当众地。',1,'meaning'),q('Which sentence uses publicly as an adverb?','The company publicly announced the safety recall.','The public company publicly building is tall.','A public announcement was public.','publicly 修饰 announced，表示公开宣布。',1,'grammar'),q('What suffix forms publicly?','-ly, added to public','-ity, added to public','-ist, added to public','public 加 -ly 形成副词 publicly。',1,'word-formation')]);
P('publish','Publish comes from Latin publicare “make public,” through Old French publier; it means to issue a book or to make information known.',[C('publish.s1','出版；发行（书刊）','The university press will publish the historian’s revised book in September, with maps and a new index.','大学出版社将于九月出版这位历史学家修订后的著作，并附地图和新索引。','The university press will publish the book / in September / with maps and a new index.','publish.s1 指制作并发行书籍、杂志等作品。','出版社安排出版修订书籍。'),C('publish.s2','发表；公布（信息）','The laboratory plans to publish its results after another team checks the calculations.','实验室计划在另一团队核对计算后发表结果。','The laboratory plans to publish its results / after another team / checks the calculations.','publish.s2 指把信息、结果或观点公开发表。','核算复核后，实验室会把结果公开。')],M('The laboratory published its results by locking them in a private cabinet so no one could read them.','The laboratory published its results by making them available in a public report after checking the calculations.','把结果锁起来不公开，不能称为发表结果。','meaning'),[q('What will the university press publish in September?','the historian’s revised book','the laboratory’s unpublished calculations only','a private voting proxy','大学出版社将出版修订后的历史著作。',1,'context'),q('When will the laboratory publish its results?','after another team checks the calculations','before anyone has checked the calculations','only after every copy is locked away','实验室会在另一团队核算后发表结果。',2,'context'),q('Which action means publish in the book sense?','issue a new novel for readers to buy or borrow','keep a manuscript in a closed drawer','appoint an editor to act as a proxy','向读者发行新小说属于出版。',1,'meaning'),q('Which historical verb gave publish its “make public” sense?','Latin publicare','Greek psychē','Latin prunum','publish 经法语来自表示“使公开”的拉丁语 publicare。',1,'word-formation')]);
P('published','Published is the past participle and adjective of publish; it describes material that has been made available to the public.',C('published.s1','已出版的；已发表的','The published study included its data tables, methods, and a note explaining the limits of the survey.','已发表的研究包含数据表、方法说明，以及解释调查局限的注释。','The published study included tables / and methods / with a note on survey limits.','published 描述已经出版、发表或公开提供的材料。','研究已经公开发行，并包含方法及局限说明。'),M('The published study was never released to readers and remained a confidential draft in the authors’ office.','The unpublished study remained a confidential draft; the published study was released for readers to consult.','未公开的保密草稿不能称为已发表研究。','meaning'),[q('What did the published study include?','data tables, methods, and a note on limitations','only the author’s private address','a pub’s menu and a publican’s tax record','已发表研究包含数据、方法和局限说明。'),q('What does published mean?','made available to the public','kept as a secret draft','scheduled to be written in the future','published 表示已经公开提供。',1,'meaning'),q('Which item is published?','a report released on the agency website','a draft saved privately and never shared','notes that remain in a locked desk','在机构网站公开的报告是已发布材料。',1,'context'),q('What is the base verb of published?','publish','publicize','pucker','published 是 publish 的过去分词形式。',1,'grammar')]);
P('publisher','Publisher is formed from publish and -er; it means a person or company that prepares and issues books, magazines, or other works.',C('publisher.s1','出版者；出版商','The publisher worked with the author to edit the manuscript, print the book, and distribute it to libraries.','出版商与作者合作编辑手稿、印制图书，并将其发行给图书馆。','The publisher worked with the author / to edit and print the book / and distribute it.','publisher 指负责制作、发行作品的个人或公司。','出版商参与编辑、印制和发行。'),M('The publisher was the printed novel itself, while the company that edited and distributed it was called the publication.','The publication was the novel; the publisher was the company that edited and distributed it.','作品是 publication；负责制作和发行作品的公司是 publisher。','word-choice'),[q('What did the publisher do with the book?','edited, printed, and distributed it','used it to collect Roman taxes','kept it as a private medical record','出版商负责编辑、印制和发行图书。'),q('Who is a publisher?','a person or company that issues books or other works','a reader who borrows a book from a library','a proxy who votes at a company meeting','publisher 指出版并发行作品的人或公司。',1,'meaning'),q('Which organization is acting as a publisher?','a firm that prepares a manuscript and sends printed copies to bookstores','a library patron who reads a finished copy','a public-health clinic mapping vaccinations','负责准备手稿并把书送至书店的公司是出版商。',1,'context'),q('Which suffix means a person or agent in publisher?','-er','-ity','-ly','publisher 中的 -er 表示从事该行为的人或机构。',1,'word-formation')]);
P('pucker','Pucker is an English verb of uncertain origin, recorded by the early modern period; it means to draw skin, lips, or fabric into small folds or wrinkles.',C('pucker.s1','起皱；皱起','The sour lemon made the child pucker her lips, and she laughed at the face in the mirror.','酸柠檬让孩子皱起嘴唇，她看着镜中的表情笑了起来。','The sour lemon made the child / pucker her lips / as she saw her reflection.','pucker 指使嘴唇、皮肤或布料形成细小皱褶。','酸味使嘴唇收拢起皱。'),M('The tailor puckered the silk by stretching it completely flat so that no folds remained.','The tailor puckered the silk by drawing it into small gathered folds.','把布料完全拉平会消除褶皱；pucker 是使其起皱。','meaning'),[q('What made the child pucker her lips?','the sour lemon','a public meeting','a freshly published book','酸柠檬使孩子皱起嘴唇。'),q('What does pucker mean?','form small folds or wrinkles','make a book available to readers','remove branches from a shrub','pucker 指形成细小皱褶。',1,'meaning'),q('Which object can pucker?','thin fabric gathered into small folds','a public-health report after publication','a pterosaur fossil that is perfectly smooth and flat','薄布料可以被抽皱形成褶子。',1,'context'),q('Which verb describes the child’s expression?','pucker','publish','prune','酸味使孩子皱起嘴唇，即 pucker。',1,'meaning')]);
P('pudding','Pudding has an uncertain history, possibly related to Old French boudin; its senses include a soft cooked dessert and, especially in British English, the sweet course at the end of a meal.',[C('pudding.s1','布丁；软质甜食','Nora baked a rice pudding with cinnamon and served it warm after the neighbors finished dinner.','邻居们吃完晚餐后，诺拉烤了肉桂米布丁并趁热端上。','Nora baked a rice pudding / with cinnamon / and served it warm after dinner.','pudding.s1 指布丁等柔软烹制的甜食。','米饭经烹煮制成甜品。'),C('pudding.s2','（英）正餐后的甜品','The waiter asked whether anyone wanted pudding after the roast and vegetables.','烤肉和蔬菜之后，服务员询问是否有人想吃餐后甜点。','The waiter asked / whether anyone wanted pudding / after the roast and vegetables.','pudding.s2 在英式用法中可泛指正餐最后的甜品。','服务员是在主菜之后询问甜品。')],M('The restaurant served pudding before the main course and called the meal complete before anyone had eaten dinner.','The restaurant served pudding after the main course as the sweet final course.','在英式餐序中，pudding 作为甜品通常在主菜之后供应。','context'),[q('What kind of pudding did Nora make?','rice pudding with cinnamon','a cold public-health report','a printed proxy form','诺拉做的是肉桂米布丁。',1,'context'),q('When did the waiter offer pudding?','after the roast and vegetables','before anyone ordered the main course','during the publisher’s editing meeting','服务员在烤肉和蔬菜之后提供甜点。',2,'context'),q('In British meal language, what can pudding mean?','the sweet course at the end of a meal','the first savory course only','the person who prints a menu','英式英语中 pudding 可指正餐后的甜品。',2,'meaning'),q('Which sentence uses pudding as a dish?','She spooned warm pudding into a bowl.','The team discussed public health.','The author chose a pseudonym.','把热布丁舀进碗里体现 pudding 指甜食。',1,'context')]);
P('puddle','Puddle is an English word of uncertain origin, recorded for a small pool of liquid; it commonly refers to rainwater gathered on the ground.',C('puddle.s1','水洼；小水坑','After the shower, a deep puddle covered the path, so cyclists slowed down before crossing it.','阵雨过后，路上出现一个深水洼，骑车人经过前都减慢了速度。','A deep puddle covered the path / after the shower / so cyclists slowed down.','puddle 指地面上积聚的一小片水或其他液体。','雨后路面上积水，骑车人需要减速。'),M('The hikers stepped over a puddle that was completely dry and contained no water or other liquid.','The hikers stepped over a puddle of rainwater that had collected in a dip in the path.','没有任何液体的干燥地面不是水洼。','meaning'),[q('Why did cyclists slow down?','a deep puddle covered the path','the path had been pruned by a gardener','a published report blocked the road','路上有深水洼，骑车人因此减速。'),q('What is a puddle?','a small pool of liquid on the ground','a false name used by an author','a medical treatment for mental illness','puddle 是地面上积聚的小片液体。',1,'meaning'),q('Which scene contains a puddle?','rainwater gathered in a shallow dip beside the curb','a dry paved path after weeks without rain','a bowl of warm rice pudding indoors','路缘旁凹处积着雨水，是水洼。',1,'context'),q('Which noun names the water left after the shower?','puddle','pucker','publisher','阵雨后路面上的积水是一处 puddle。',1,'meaning')]);
P('pueblo','Pueblo comes from Spanish pueblo, “people or town,” from Latin populus; in English it names a member of Pueblo peoples or their traditional communal village.',C('pueblo.s1','普韦布洛人；土坯村','The guide described how Pueblo families built multistory adobe homes and maintained community traditions in the Southwest.','导览员介绍了美国西南部普韦布洛家庭如何建造多层土坯住宅并传承社区传统。','The guide described Pueblo families / who built adobe homes / and maintained community traditions.','pueblo.s1 可指美国西南部一些原住民族群成员，也可指其传统村落。','例句提到族群、土坯住宅和社区传统。'),M('The guide described a Pueblo village as a temporary ice-fishing camp built from canvas on an Arctic sea.','The guide described a Pueblo village as a Southwestern community with traditional adobe homes.','普韦布洛村落与美国西南部土坯住宅相关，不是北极冰钓营地。','meaning'),[q('What kind of homes did the guide describe?','multistory adobe homes','portable canvas tents on sea ice','small wooden boats used for fishing','导览员介绍普韦布洛家庭的多层土坯住宅。'),q('What can pueblo refer to in English?','a Pueblo person or a traditional communal village','a licensed British pub','a Greek word meaning “false name”','pueblo 可指普韦布洛族人或传统村落。',1,'meaning'),q('Where are Pueblo communities traditionally associated?','the American Southwest','the Arctic Ocean','the Roman Republic only','普韦布洛民族和村落与美国西南部相关。',1,'context'),q('Which language supplied pueblo to English?','Spanish','Old Norse','Scottish Gaelic','pueblo 来自西班牙语 pueblo。',1,'word-formation')]);
P('puff','Puff is an English word likely imitative of a short burst of breath; as a verb it means to blow in short bursts, and as a noun it can mean a short breath or cloud of smoke.',[C('puff.s1','短促地吹气；喷出','The child puffed gently on the hot soup until it was cool enough to taste.','孩子对着热汤轻轻吹气，直到温度适合品尝。','The child puffed gently / on the hot soup / until it cooled.','puff.s1 作动词指短促地吹气或喷出气体。','短促吹气让汤变凉。'),C('puff.s2','一口气；一阵烟雾','A puff of smoke escaped from the old stove when the cook opened its iron door.','厨师打开旧炉子的铁门时，一股烟冒了出来。','A puff of smoke escaped / from the old stove / when its door opened.','puff.s2 作名词可指一阵短促的气息、风或烟雾。','例句中的烟短促地从炉门逸出。')],M('The child puffed on the soup by inhaling it through a straw and pulling all the steam into her mouth.','The child puffed on the soup by blowing short breaths across its hot surface.','对热汤 puff 是向外短促吹气，而不是把蒸汽吸入口中。','meaning'),[q('How did the child cool the soup?','by blowing short breaths across it','by pulling all the steam through a straw','by placing it in a freezer overnight','孩子对热汤短促吹气使其降温。',1,'context'),q('What escaped when the stove door opened?','a short cloud of smoke','a written proxy','a bowl of pudding','炉门打开时冒出一阵烟。',2,'context'),q('Which sentence uses puff as a noun?','A puff of wind lifted the paper napkin.','She puffed on the soup.','The publisher will puff the new novel.','a puff of wind 中 puff 是名词，指一阵风。',2,'grammar'),q('Why is puff considered likely imitative?','its sound resembles a short burst of breath','it comes from a Greek word for village','it is formed from publish and -er','puff 的发音模仿短促呼气的声音。',1,'word-formation')]);
P('puffin','Puffin is recorded in English from the mid-14th century as poffoun; its name may relate to a feature of its appearance or derive from a Celtic word reshaped under the influence of puff, so the origin remains uncertain.',C('puffin.s1','角嘴海雀；海鹦','The puffin carried small fish in its brightly colored bill as it returned to its burrow on the rocky island.','海鹦用色彩鲜艳的喙叼着小鱼，返回岩岛上的洞穴。','The puffin carried small fish / in its brightly colored bill / as it returned to its burrow.','puffin 是北大西洋海鸟，喙较大，常在洞穴中筑巢。','海鸟衔鱼回到岩岛洞穴，符合其潜水捕食和穴居习性。'),M('The guide identified the puffin as a flightless freshwater songbird that nests in trees far from the sea.','The guide identified the puffin as a diving seabird that nests in burrows on rocky coasts.','puffin 是海鸟，潜水捕鱼并常在海岸洞穴筑巢，不是淡水树栖鸟。','meaning'),[q('What did the puffin carry back to its burrow?','small fish','a public-health report','a strip of pumice','海鹦叼着小鱼返回洞穴。'),q('What is a puffin?','a diving seabird with a large colorful bill','a flightless freshwater songbird that nests in trees','a Mesozoic flying reptile with a membrane wing','puffin 是喙大、会潜水的海鸟。',1,'meaning'),q('Where did the puffin return to nest?','a burrow on a rocky island','a tree beside an inland pond','a hole in a paper ticket','例句说海鹦回到岩岛洞穴。',1,'context'),q('What is known about the origin of puffin?','it may relate to the bird’s appearance or a Celtic word, but the history is uncertain','it certainly comes from Latin purificare','it is a blend of public and -ity','词源资料提出外观或凯尔特语关联，但仍不确定。',1,'word-formation')]);
P('pul','Pul is borrowed through Persian pūl and Turkish pul, ultimately linked to Late Greek phollis and Latin follis for a small coin or money bag; in Afghanistan it is one hundredth of an afghani.',C('pul.s1','普尔（阿富汗货币单位）','The museum label explained that the old Afghan coin was worth one hundredth of an afghani, or one pul.','博物馆标签说明，这枚旧阿富汗硬币相当于一阿富汗尼的百分之一，即一个普尔。','The old Afghan coin was worth / one hundredth of an afghani / or one pul.','pul.s1 指阿富汗货币单位阿富汗尼的百分之一。','标签给出了 pul 与 afghani 之间的比例。'),M('The cashier exchanged one pul for a hundred afghanis because each pul was worth one hundred full afghanis.','The cashier exchanged one hundred pul for one afghani.','一个 pul 是一阿富汗尼的百分之一，方向不能颠倒。','measurement'),[q('How much of an afghani was the old coin worth?','one hundredth','one hundred full afghanis','one half','一个 pul 是一阿富汗尼的百分之一。'),q('What is a pul?','a small Afghan currency unit','a British pub keeper','a tool used to lift a heavy load','pul 是阿富汗的小额货币单位。',1,'meaning'),q('How many pul make one afghani in the described system?','one hundred','ten','one thousand','一百个 pul 等于一阿富汗尼。',1,'measurement'),q('Which language forms are associated with the word’s route?','Persian pūl and Turkish pul','Greek psychē and Latin sōma','French pompon and Greek pepon','词源经土耳其语 pul 与波斯语 pūl。',1,'word-formation')]);
P('pull','Pull comes from Middle English pullen, of uncertain deeper origin; it means drawing something toward oneself, removing it by force, or the force or attraction involved.',[C('pull.s1','拉；拖；扯','The rescue team pulled the raft toward the bank while two people held the safety line.','两名队员拉住安全绳时，救援队把木筏拖向岸边。','The rescue team pulled the raft / toward the bank / while holding the safety line.','pull.s1 指用力把物体向自己或某一方向移动。','救援队施力使木筏移向河岸。'),C('pull.s2','拔出；抽出','The dentist pulled the damaged tooth after the patient agreed to the treatment plan.','患者同意治疗方案后，牙医拔掉了受损的牙齿。','The dentist pulled the damaged tooth / after the patient agreed / to the treatment plan.','pull.s2 指用持续的力把嵌入或固定的东西拔出。','牙齿被从牙床中拔出。'),C('pull.s3','拉力；吸引力','The old magnet still had enough pull to lift several steel clips from the desk.','这块旧磁铁仍有足够的吸力，能从桌上吸起几枚钢夹。','The old magnet had enough pull / to lift steel clips / from the desk.','pull.s3 作名词可指拉力，也可指吸引人的力量。','磁铁对钢夹施加吸引力。')],M('The rescuer pulled the raft by pushing it away from the bank, and the raft moved toward the rescuer.','The rescuer pulled the raft toward the bank by drawing it closer with the line.','pull 是朝某方向施力拉动，不是把物体推离自己。','meaning'),[q('Where did the rescue team move the raft?','toward the bank','away from the river and into the sky','into the dentist’s office','救援队把木筏拉向河岸。',1,'context'),q('What did the dentist pull?','the damaged tooth','the raft’s safety line','several steel clips with a magnet','牙医拔掉的是受损牙齿。',2,'context'),q('What does pull mean as a noun in the magnet example?','the force of attraction','a printed book','the power to publish a report','这里 pull 指磁铁的吸力。',3,'meaning'),q('Which sentence uses pull for social influence?','The candidate’s reputation gave her strong pull with local voters.','The dentist pulled the tooth after consent.','They pulled the raft toward the bank.','对选民的影响力是 pull 的引申名词义。',1,'meaning')]);
P('pull out','Pull out combines pull with out; it means to withdraw or leave a place, or to remove something from where it is fixed.',[C('pull out.s1','撤出；驶离','The train pulled out of the station at 6:10, just after the platform doors closed.','站台门刚关上，火车便于6点10分驶离车站。','The train pulled out / of the station at 6:10 / after the doors closed.','pull out.s1 指离开某地或从某事中撤出。','火车从车站出发驶离。'),C('pull out.s2','拔出；抽出','She pulled out the thorn with tweezers and cleaned the small wound.','她用镊子拔出刺，并清理了小伤口。','She pulled out the thorn / with tweezers / and cleaned the wound.','pull out.s2 指把嵌入或固定在某处的东西拔出来。','刺从皮肤中被镊子取出。')],M('The train pulled out of the station by remaining on the platform and never beginning its journey.','The train pulled out of the station by leaving the platform and beginning its journey.','pull out of a station 表示驶离车站，不是停留在站台。','meaning'),[q('When did the train pull out?','at 6:10 after the platform doors closed','before it arrived at the station','after it had returned to the depot','火车在站台门关闭后于6点10分驶离。',1,'context'),q('How did she pull out the thorn?','with tweezers','by asking a publisher to print it','by waiting for the train to leave','她用镊子拔出刺。',2,'context'),q('Which sentence uses pull out to mean “withdraw”?','The company pulled out of the deal before signing.','He pulled out a splinter with pliers.','She pulled the rope toward her.','公司退出交易是撤出的用法。',1,'meaning'),q('Which sentence uses the physical-removal sense?','The mechanic pulled out the broken fuse.','The train pulled out of the station.','The athlete pulled the team together.','把坏掉的保险丝从插座中取出是抽出的用法。',2,'meaning')]);
P('pulley','Pulley entered English through Old French polie or pulie and Medieval Latin poliva; its name may ultimately relate to a Greek word for a small pivot. It is a grooved wheel that redirects a rope to lift a load.',C('pulley.s1','滑轮；滑车','The crew ran a rope over a pulley fixed above the well to raise the heavy water bucket.','工作人员把绳子绕过固定在井上方的滑轮，以提起沉重的水桶。','The crew ran a rope over a pulley / fixed above the well / to raise the bucket.','pulley 指绳索绕过的带槽轮，可改变施力方向并帮助提升重物。','井上方的滑轮让工作人员可以拉绳提桶。'),M('The crew used a pulley as a flat board with no wheel or groove, so the rope could not change direction.','The crew used a grooved wheel as a pulley so the rope could change direction and raise the bucket.','pulley 是带槽的轮子，不是没有轮槽的平板。','meaning'),[q('What did the pulley help the crew raise?','a heavy water bucket','the station platform doors','a dried plum snack','滑轮帮助工作人员提起水桶。'),q('What is a pulley?','a grooved wheel over which a rope runs','a small Afghan coin','a soft cooked dessert','pulley 是绳索绕过的带槽轮。',1,'meaning'),q('How did the pulley help at the well?','it redirected the rope so the bucket could be raised','it measured how many liters the bucket held','it kept the rope from moving at all','滑轮改变绳索方向，让水桶更易提起。',1,'context'),q('Which older form supplied pulley to English?','Old French polie or pulie','Greek pepon','Latin publicanus','pulley 经法语形式进入英语。',1,'word-formation')]);
P('pullulate','Pullulate came from Latin pullulare, “put forth or sprout,” from pullulus, a young animal; it means to germinate or to teem with new growth or numerous living things.',C('pullulate.s1','萌发；大量滋生','After the spring rains, seedlings pullulated across the cleared plot and insects soon pullulated among the leaves.','春雨过后，幼苗在清理过的地块上大量萌发，昆虫很快也在叶间繁生。','Seedlings pullulated across the plot / and insects soon pullulated / among the leaves.','pullulate 指萌发、生长，也可指生命或事物大量滋生、挤满某处。','植物和昆虫都呈现大量生长或繁殖。'),M('The sterile greenhouse pullulated with seedlings even though no seeds, water, or soil had ever been introduced.','The damp greenhouse pullulated with seedlings after seeds were planted and regularly watered.','pullulate 描述萌发生长，不会在完全没有种子和生长条件时凭空发生。','meaning'),[q('What spread across the cleared plot after spring rains?','seedlings','steel clips lifted by a magnet','a published medical study','春雨后幼苗在地块上大量萌发。'),q('What does pullulate mean?','sprout or teem with many new living things','pay one hundredth of an afghani','remove a thorn with tweezers','pullulate 指萌发或大量滋生。',1,'meaning'),q('Where did insects pullulate in the example?','among the leaves','inside the train station clock','on the publisher’s book cover','例句说昆虫在叶间大量繁生。',1,'context'),q('Which Latin form gave rise to pullulate?','pullulare, “put forth or sprout”','pulsare, “strike or beat”','pūl, “money”','pullulate 来自表示萌发、生长的拉丁动词。',1,'word-formation')]);
P('pulp','Pulp comes through Old French pulpe from Latin pulpa, “flesh or soft tissue”; it can mean the soft flesh of fruit or a soft mass of wood fibers used in papermaking.',[C('pulp.s1','果肉','The blender turned the ripe mango into smooth pulp for the chutney.','搅拌机把成熟的芒果打成果肉糊，用来制作酸辣酱。','The blender turned the mango / into smooth pulp / for the chutney.','pulp.s1 指水果柔软多汁的果肉部分。','芒果被打碎成柔软的果肉。'),C('pulp.s2','纸浆','The mill mixes recycled paper pulp with water before pressing the fibers into new sheets.','造纸厂先把回收纸浆与水混合，再将纤维压制成新纸张。','The mill mixes recycled paper pulp / with water / before pressing new sheets.','pulp.s2 指造纸用的柔软木纤维或纸纤维浆料。','纤维浆料经压制形成新纸。')],M('The mill made new sheets by pressing dry steel clips instead of mixing paper pulp with water.','The mill made new sheets by mixing paper pulp with water and pressing the fibers.','钢夹不是造纸纤维；造纸需要纸浆与水混合压制。','meaning'),[q('What did the blender make from the ripe mango?','smooth fruit pulp','a pul of Afghan currency','a grooved lifting wheel','搅拌机把芒果打成果肉糊。',1,'context'),q('What was mixed with water at the paper mill?','recycled paper pulp','ripe mango pulp for chutney','pumice stone dust for polishing','造纸厂把回收纸浆与水混合。',2,'context'),q('Which meaning of pulp fits “wood pulp”?','soft fibers used to make paper','the edible flesh of a fruit','a quick blow with a fist','wood pulp 是用于造纸的纤维浆料。',2,'meaning'),q('Which Latin word is behind pulp?','pulpa, “flesh or soft tissue”','pulsus, “a beat”','pteron, “wing”','pulp 经法语来自表示柔软组织的拉丁词。',1,'word-formation')]);
P('pulsar','Pulsar is a 1968 blend of pulsating and star, modeled on quasar; it names a rapidly rotating compact stellar remnant that emits regular pulses of radiation.',C('pulsar.s1','脉冲星','The observatory detected a pulsar whose radio pulses arrived at extremely regular intervals as the neutron star rotated.','天文台探测到一颗脉冲星；随着中子星旋转，它发出的射电脉冲以极规律的间隔到达。','The observatory detected a pulsar / whose radio pulses arrived regularly / as the star rotated.','pulsar 指快速旋转并发出规律辐射脉冲的致密恒星遗迹。','射电脉冲随中子星旋转而规律到达。'),M('The astronomer called the steady planet a pulsar even though it emitted no periodic radiation and did not rotate.','The astronomer called the rotating neutron star a pulsar because it emitted periodic radio pulses.','脉冲星以旋转和规律辐射脉冲为特征。','meaning'),[q('What did the observatory detect?','regular radio pulses from a rotating neutron star','a public-health map of vaccination rates','a storm cloud over a train station','天文台探测到旋转中子星发出的规律射电脉冲。'),q('What is a pulsar?','a compact rotating stellar remnant that emits pulses of radiation','a star that produces no radiation and does not rotate','a device that pumps liquid into a pipe','pulsar 是发出辐射脉冲的旋转致密星体。',1,'meaning'),q('Why did the radio pulses arrive at regular intervals?','the neutron star was rotating','the telescope was publishing the signal','a pulley was lifting the antenna','星体旋转使观测到的脉冲以规律间隔出现。',1,'context'),q('What words blend to form pulsar?','pulsating + star','public + affairs','pulp + paper','pulsar 是 pulsating star 的合成缩略词。',1,'word-formation')]);
P('pulsate','Pulsate was formed from Latin pulsare “to beat or strike,” a frequentative of pellere; it means to throb or expand and contract rhythmically.',C('pulsate.s1','有节奏地跳动；搏动','A faint red light seemed to pulsate beneath the machine’s panel each time the engine started.','每次发动机启动时，面板下方的微弱红灯似乎都会有节奏地闪动。','A faint red light seemed to pulsate / beneath the panel / each time the engine started.','pulsate 指心脏、血管或光等有规律地搏动、起伏或闪动。','红灯随发动机启动而有节奏地明灭。'),M('The red light pulsated in a steady rhythm while it remained completely dark and never changed.','The red light pulsated in a steady rhythm, brightening and dimming beneath the panel.','保持全黑且没有变化的灯不会有节奏地搏动或闪动。','meaning'),[q('When did the red light seem to pulsate?','each time the engine started','only after the panel was removed forever','while the machine remained unplugged in storage','发动机启动时，红灯有节奏地闪动。'),q('What does pulsate mean?','throb or change rhythmically','publish a result for public readers','sprout in great numbers','pulsate 指有节奏地跳动或变化。',1,'meaning'),q('Which body part can pulsate?','a blood vessel as blood moves through it','a printed book on a shelf','a dry thorn removed with tweezers','血液流动时，血管可以搏动。',1,'context'),q('Which Latin verb is related to pulsate?','pulsare, “to beat or strike”','pullulare, “to sprout”','publicare, “to make public”','pulsate 与表示敲击、跳动的拉丁语 pulsare 有关。',1,'word-formation')]);
P('pulse','Pulse comes through Old French from Latin pulsus, “a beating or thrust”; it can be a felt heartbeat, a short wave of energy, or a rhythmic beating action.',[C('pulse.s1','脉搏；脉率','The nurse counted the runner’s pulse at the wrist after the race and recorded the beats per minute.','比赛后，护士在跑者手腕处数脉搏，并记录每分钟的跳动次数。','The nurse counted the runner’s pulse / at the wrist / and recorded beats per minute.','pulse.s1 指能在手腕或颈部感到的规律心跳。','护士通过手腕脉搏计数评估心跳。'),C('pulse.s2','脉冲；短暂波动','The sensor sent a short pulse of light through the sample and measured how much returned.','传感器向样品发出一束短促光脉冲，并测量返回的光量。','The sensor sent a short pulse of light / through the sample / and measured the return.','pulse.s2 指声音、光或电流中短暂而集中的波动。','传感器发出短促的光信号。'),C('pulse.s3','搏动；有节奏地跳动','The bass seemed to pulse through the walls, keeping time with the dancers’ steps.','低音似乎隔着墙壁有节奏地震动，与舞者的步伐保持同步。','The bass seemed to pulse / through the walls / in time with the dancers’ steps.','pulse.s3 作动词，指强烈而有节奏地跳动或移动。','低音随舞步产生规律振动。')],M('The nurse said the runner had a pulse of zero beats per minute while clearly feeling a regular heartbeat at the wrist.','The nurse recorded a regular pulse of seventy-two beats per minute at the runner’s wrist.','感到规律心跳时，脉搏不可能同时为零。','measurement'),[q('Where did the nurse count the runner’s pulse?','at the wrist','through a sample with a light sensor','along the floor beneath the dancers','护士在跑者的手腕处数脉搏。',1,'context'),q('What did the sensor send through the sample?','a short pulse of light','a heartbeat measured at the wrist','a bass note through a wall','传感器发出短促光脉冲。',2,'context'),q('What did the bass do in the dance hall?','it pulsed through the walls in rhythm','it measured the runner’s beats per minute','it was filed as a published study','低音有节奏地穿过墙壁震动。',3,'context'),q('Which noun phrase names the heartbeat you can feel?','a pulse at the wrist','a pulse of light','the pulse of bass through a wall','手腕上能摸到的心跳叫 pulse。',1,'meaning')]);
P('pulverise','Pulverise is the British spelling of pulverize, from Late Latin pulverizare and Latin pulvis, pulveris “dust”; it means to grind into powder or figuratively to destroy decisively.',[C('pulverise.s1','磨成粉；击溃','The mill pulverised the dried limestone into a fine powder for the conservation mortar.','磨坊把干石灰岩磨成细粉，用于修复砂浆。','The mill pulverised the limestone / into fine powder / for conservation mortar.','pulverise.s1 指把固体研磨、击碎成粉末。','石灰岩经过研磨变成细粉。') ,C('pulverise.s1','彻底击败；摧毁','The visiting side pulverised its rivals by scoring six goals before halftime.','客队在半场前打进六球，彻底击败了对手。','The visiting side pulverised its rivals / by scoring six goals / before halftime.','pulverise 也可非正式地比喻为彻底摧毁或击败。','悬殊比分体现压倒性胜利。')],M('The mill pulverised the limestone by preserving every piece as one unbroken block for the mortar.','The mill pulverised the limestone by grinding it into fine particles for the mortar.','保留整块石灰岩与磨成粉末相反。','meaning'),[q('What was the limestone turned into?','fine powder','a smooth bowl of rice pudding','a public-health report','石灰岩被磨成修复用细粉。',1,'context'),q('How did the visiting side pulverise its rivals?','by scoring six goals before halftime','by withdrawing from the game before kickoff','by letting the rivals score every goal','客队半场前攻入六球，压倒性地击败对手。',1,'context'),q('What does pulverise mean literally?','grind a solid into powder','draw a raft toward a bank','make a short wave of light','pulverise 的字面义是磨成粉末。',1,'meaning'),q('Which Latin form is behind pulverise?','pulvis, pulveris “dust”','pulsus “beat”','pūl “money”','pulverise 源自表示灰尘或粉末的拉丁词。',1,'word-formation')]);
P('pulverization','Pulverization is formed from pulverize and -ation; it means reducing material to fine particles or, figuratively, complete destruction.',C('pulverization.s1','粉碎；研磨成粉；彻底摧毁','The report measured the pulverization of the rock sample, then used the word figuratively for the team’s crushing defeat.','报告测量了岩样的粉碎程度，随后又用这个词比喻球队遭到的惨败。','The report measured rock pulverization / then used the word figuratively / for a crushing defeat.','pulverization 指将材料磨成细粒，也可比喻彻底摧毁或击败。','岩石成粉和球队惨败分别展示字面与比喻义。'),M('The report described pulverization as keeping the rock sample intact and preventing any particles from breaking off.','The report described pulverization as grinding the rock sample into fine particles.','保持样品完整与粉碎成细粒相反。','meaning'),[q('What happened to the rock sample during pulverization?','it was reduced to fine particles','it was kept intact with no fragments','it was turned into a living pterosaur','样品被粉碎成细粒。'),q('What did pulverization mean figuratively for the team?','a crushing defeat','a punctual arrival','a careful psychological analysis','球队遭遇的惨败是 pulverization 的比喻用法。',1,'context'),q('What does the suffix -ation do in pulverization?','forms a noun for an action or process','marks a person who publishes a book','changes an adjective into an adverb','-ation 在此构成表示过程的名词。',1,'word-formation'),q('Which operation is pulverization?','grinding a mineral sample into fine grains','lifting a bucket with a grooved wheel','measuring a heartbeat per minute','把矿物样本磨成细粒属于粉碎。',1,'meaning')]);
P('pumice','Pumice came through Old French and Late Latin pomex or pumex; its porous volcanic stone was associated with foam because its texture looks frothy.',C('pumice.s1','浮岩；浮石','The conservator rubbed a small piece of pumice over the rough edge to smooth the surface without using metal.','修复师用一小块浮石摩擦粗糙边缘，使表面变光滑而不使用金属工具。','The conservator rubbed pumice / over the rough edge / to smooth the surface.','pumice 指多孔、质轻的火山岩，也可用作磨料。','浮石的粗糙表面能磨平材料边缘。'),M('The conservator chose pumice because the dense stone sank instantly and dissolved before touching the surface.','The conservator chose light, porous pumice to abrade the rough edge gently.','浮石多孔轻质，常用作磨料，不是密实且遇水溶解的材料。','meaning'),[q('What did the conservator use pumice to do?','smooth a rough edge','measure a runner’s pulse','publish an article in a journal','修复师用浮石磨平粗糙边缘。'),q('What is pumice?','a light, porous volcanic rock','a soft fruit flesh used in chutney','a British term for a public house','pumice 是轻质多孔的火山岩。',1,'meaning'),q('Why was pumice suitable for the edge?','its abrasive surface could smooth the material','it was a soft liquid that filled the roughness','it was a grooved wheel that lifted the object','浮石可作磨料来打磨边缘。',1,'context'),q('What does its historical foam association describe?','the porous, frothy-looking texture of pumice','the regular beat of a pulse','the five ingredients in a drink','浮石的多孔外观让人联想到泡沫。',1,'word-formation')]);
P('pump','Pump probably entered English from Middle Dutch or Middle Low German words for a water conduit, possibly imitative; it can name a machine, the act of moving liquid or air, or persistent questioning.',[C('pump.s1','泵；泵具','The mechanic replaced the faulty pump that moved coolant through the engine.','机械师更换了故障的泵，这个泵负责让冷却液在发动机中循环。','The mechanic replaced the faulty pump / that moved coolant / through the engine.','pump.s1 指推动液体或气体流动的机器或装置。','该设备让冷却液在发动机内循环。'),C('pump.s2','用泵抽送；打气','They pumped water out of the flooded basement before the electrician inspected the wiring.','电工检查线路前，他们先用泵抽出地下室的积水。','They pumped water out / of the flooded basement / before the wiring inspection.','pump.s2 作动词表示用泵输送液体或空气，也可指反复压动手柄。','水被抽出地下室。'),C('pump.s3','盘问；追问出','The interviewer pumped the witness for details but stopped when the lawyer objected.','采访者不断追问证人细节，但律师提出异议后便停了下来。','The interviewer pumped the witness / for details / but stopped at the objection.','pump.s3 可比喻指反复提问以套取信息。','采访者连续追问证人。')],M('The crew pumped water into the basement to remove the flood, filling the room instead of draining it.','The crew pumped water out of the basement to remove the flood.','要排走积水，应把水泵出地下室，而不是泵入。','meaning'),[q('What did the faulty pump move through the engine?','coolant','pulp from a mango','a short pulse of light','泵推动冷却液在发动机中循环。',1,'context'),q('What did the crew do before the wiring inspection?','pumped floodwater out of the basement','pumped more water into the basement','pulled out the electrician’s notes','他们在电工检查前抽出了地下室积水。',2,'context'),q('Why did the interviewer pump the witness?','to obtain more details by repeated questions','to move air into a tire','to turn the witness into a published author','采访者通过反复提问套取细节。',3,'context'),q('Which sentence uses pump as a noun?','The pump circulated water through the engine.','They pumped water out of the basement.','The reporter pumped the witness for details.','The pump 指推动液体的装置。',1,'grammar')]);
P('pump in','Pump in combines pump with in; it means to force liquid into a space or, figuratively, to invest large amounts of money or resources.',[C('pump in.s1','泵入；注入','The crew pumped fresh water in through a hose until the storage tank reached its marked level.','工作人员通过软管泵入清水，直到储水箱达到标记水位。','The crew pumped fresh water in / through a hose / until the tank reached its marked level.','pump in.s1 指用泵把液体或气体送入容器或空间。','清水经软管进入储水箱。'),C('pump in.s2','大量投入（资金、资源）','The investors pumped money in to keep the factory open while it retrained workers for safer production.','投资者向工厂大量注资，使其在培训员工进行更安全生产期间继续运营。','The investors pumped money in / to keep the factory open / during safety retraining.','pump in.s2 比喻指大量投入资金或其他资源。','投资者注入资金维持工厂运营。')],M('The crew pumped water in through the hose to empty the tank, forcing all the liquid out.','The crew pumped water out through the hose to empty the tank.','pump in 是泵入；要排空储水箱，应 pump out。','meaning'),[q('How did fresh water reach the storage tank?','the crew pumped it in through a hose','the crew pumped it out through a hose','it flowed from the tank into the hose','工作人员通过软管把清水泵入水箱。',1,'context'),q('Why did investors pump money in?','to keep the factory open during worker retraining','to drain the tank before an inspection','to publish a quarterly journal','注资是为了让工厂在培训期间继续运营。',2,'context'),q('Which sentence uses the figurative sense of pump in?','The city pumped funds in to expand the clinic.','The crew pumped water in through the pipe.','The nurse checked the patient’s pulse.','向诊所大量投入资金是比喻用法。',2,'meaning'),q('What direction does pump in express?','into a container or project','out of a container only','away from a person without a destination','pump in 表示向内注入或投入。',1,'meaning')]);
P('pumpkin','Pumpkin is a 17th-century alteration of pumpion or pompion, from French pompon, Latin pepo, and Greek pepon “melon”; it names a large edible squash and its carved festival lantern.',[C('pumpkin.s1','南瓜','The cook roasted pumpkin with sage and lentils for the autumn market lunch.','厨师把南瓜与鼠尾草和扁豆一起烤制，作为秋季集市午餐。','The cook roasted pumpkin / with sage and lentils / for lunch.','pumpkin.s1 指这种大型可食用瓜类及其果实。','南瓜被作为食材烤制。'),C('pumpkin.s2','南瓜灯','The children carved a pumpkin, placed a candle inside, and set the glowing lantern beside the doorway.','孩子们雕刻了一个南瓜，在里面放上蜡烛，并把发光的南瓜灯放在门边。','The children carved a pumpkin / placed a candle inside / and set the lantern by the door.','pumpkin.s2 指挖空雕刻后用作节庆灯笼的南瓜。','果实被雕刻并放入蜡烛作灯笼。')],M('The children called the whole uncut fruit a pumpkin lantern even though they had not carved or hollowed it.','The children carved and hollowed the pumpkin before calling it a pumpkin lantern.','南瓜灯需要把南瓜雕刻、挖空并放入灯光。','meaning'),[q('How was pumpkin prepared for the autumn lunch?','roasted with sage and lentils','carved and used as a candle lantern','pumped into the storage tank','厨师把南瓜与香草和扁豆一起烤制。',1,'context'),q('What did the children place inside the carved pumpkin?','a candle','a pulley','a published report','孩子们在雕刻好的南瓜里放了蜡烛。',2,'context'),q('What does pumpkin mean in the lunch example?','an edible squash used as food','a carved festival lantern','a fruit pulp used to make paper','例句中的 pumpkin 指可食用的瓜类果实。',1,'meaning'),q('Which Greek word is in the history of pumpkin?','pepon, “melon”','pteron, “wing”','psychē, “mind”','pumpkin 经法语、拉丁语追溯至希腊语 pepon。',1,'word-formation')]);
P('punch','Punch has several histories: the verb came through Old French ponchonner “to thrust or pierce”; the drink’s origin is disputed, though it is commonly linked to Hindi pañc “five.” Its senses include striking, making a hole, a blow/tool or force, and a mixed drink.',[C('punch.s1','用拳头打；冲击','The boxer punched the padded target once, then lowered his hands when the trainer called time.','拳击手用拳头击打了一次带垫靶，教练喊停后便放下双手。','The boxer punched the padded target / once / then lowered his hands.','punch.s1 作动词表示用拳头击打。','拳击手以拳头击中靶子。'),C('punch.s2','打孔；冲压','The clerk punched two holes in the paper ticket so the inspector could see it had been used.','工作人员在纸票上打了两个孔，检票员便能看出它已使用。','The clerk punched two holes / in the paper ticket / to mark it as used.','punch.s2 作动词表示用工具打孔或冲压出形状。','纸票被打孔作为使用标记。'),C('punch.s3','一拳；打孔器；效力','The joke lacked punch until the comedian paused before delivering its final line.','喜剧演员在说出最后一句前停顿了一下，笑话这才有了感染力。','The joke lacked punch / until the comedian paused / before its final line.','punch.s3 可指一拳、打孔工具，也可比喻为有力或感染力。','这里 punch 指笑话的表现力。'),C('punch.s4','潘趣酒；混合饮料','At the picnic, the host served a bowl of fruit punch made with juice, water, sugar, and spices.','野餐时，主人端上一碗用果汁、水、糖和香料调制的潘趣酒。','The host served fruit punch / made with juice and water / at the picnic.','punch.s4 指由多种成分混合调制的饮料。','饮料由果汁、水、糖和香料混合而成。')],M('The clerk punched the ticket by leaving it unmarked and untouched, so the inspector could not tell it had been used.','The clerk punched two holes in the ticket to mark it as used.','打孔会在票上留下标记；完全不碰票不能称为 punch。','meaning'),[q('What did the boxer punch?','a padded target','a bowl of fruit drink','a paper ticket with a hole punch','拳击手击打的是带垫靶。',1,'context'),q('Why did the clerk punch holes in the ticket?','to show it had been used','to make a mixed fruit drink','to give a joke more comic force','打孔标记纸票已使用。',2,'context'),q('What did the joke lack before the pause?','impact or force','a hole made by a tool','water, sugar, and spice','这里 punch 指笑话的感染力。',3,'meaning'),q('What was served at the picnic?','a mixed fruit drink','a set of padded boxing targets','a paper ticket with punched holes','野餐时主人端上了混合果汁饮料。',4,'context')]);
P('punctual','Punctual derives from Medieval Latin punctualis, from punctum “point”; it describes a person who is not late or an event that occurs at its set time.',[C('punctual.s1','准时的；守时的','The punctual interpreter arrived twenty minutes early to check the microphones before the hearing.','守时的口译员提前二十分钟到场检查听证会的麦克风。','The punctual interpreter arrived early / to check the microphones / before the hearing.','punctual.s1 描述按约定时间到达或做事、不迟到的人。','口译员准时甚至提前到场。'),C('punctual.s2','按时发生的','The bus service remained punctual through the snowstorm, with every departure leaving at its posted time.','暴风雪期间公交服务仍准点运行，每班车都按公布时间发车。','The bus service remained punctual / through the snowstorm / with each departure on schedule.','punctual.s2 描述事件或服务按照预定时间发生。','各班车按公布时间发车。')],M('The punctual interpreter arrived forty minutes after the hearing had ended and missed the scheduled start.','The punctual interpreter arrived before the scheduled start and checked the microphones.','听证结束后才到场属于迟到，不是准时。','meaning'),[q('Why did the interpreter arrive early?','to check the microphones before the hearing','to miss the scheduled start','to publish the hearing results','口译员提前检查听证会麦克风。'),q('How did buses remain punctual during the snowstorm?','each departure left at its posted time','each bus departed whenever its driver felt ready','all routes were canceled without notice','公交车仍按公布时间发车。',2,'context'),q('Which usage describes an event rather than a person?','The train was punctual despite the snow.','The punctual interpreter checked the microphone.','A punctual student arrived before class.','列车按时运行中 punctual 描述事件。',2,'grammar'),q('Which root idea is reflected in Latin punctum?','a point, as in a fixed point in time','a young animal sprouting','a false name','punctual 与表示“点”的拉丁语 punctum 有关。',1,'word-formation')]);
P('punctuality','Punctuality is formed from punctual and -ity; it means the habit or quality of arriving or acting at the agreed time.',C('punctuality.s1','准时；守时','The clinic values punctuality because late arrivals can delay every patient booked after them.','诊所重视准时，因为迟到会耽误后面预约的每一位患者。','The clinic values punctuality / because late arrivals / can delay later patients.','punctuality 指按约定时间到达或办事的品质与习惯。','准时能避免后续预约患者被延误。'),M('The clinic praised her punctuality when she arrived an hour after the appointment and made every later patient wait.','The clinic praised her punctuality when she arrived before the appointment and checked in on time.','迟到并造成他人等待不是守时。','meaning'),[q('Why does the clinic value punctuality?','late arrivals can delay later patients','early arrivals always cancel every appointment','the public wants the clinic to publish a book','诊所重视准时，以免延误后续患者。'),q('What does punctuality mean?','the habit of being on time','the act of making holes in paper','the quality of having a strong comic effect','punctuality 指守时的品质或习惯。',1,'meaning'),q('Which action shows punctuality at a hearing?','arriving before the scheduled start with materials ready','entering after the hearing has ended','asking the clerk to pump water from the room','开庭前到场并准备好材料体现守时。',1,'context'),q('Which suffix forms punctuality?','-ity','-ize','-ly','-ity 把 punctual 转成表示品质的名词。',1,'word-formation')]);
P('punctually','Punctually is punctual plus -ly; it is an adverb meaning at the appointed or expected time, neither late nor early.',C('punctually.s1','准时地；按时地','The ferry departed punctually at 7:30, so passengers who arrived later had to wait for the next crossing.','渡船于7点30分准时出发，因此迟到的乘客只好等下一班。','The ferry departed punctually / at 7:30 / so late passengers missed it.','punctually 修饰动作，表示动作在规定时间准时发生。','渡船按公布时刻出发。'),M('The ferry departed punctually at 7:30 after delaying its departure until 8:15.','The ferry departed punctually at 7:30 as scheduled.','8点15分出发而非7点30分不符合准点发船。','meaning'),[q('When did the ferry depart punctually?','at 7:30','at 8:15 after a delay','at an unknown time the next day','渡船在公布的7点30分准时出发。'),q('What does punctually mean?','at the appointed time','with an added hole in a ticket','in a way that studies the mind','punctually 表示在规定时间准时地。',1,'meaning'),q('Which sentence uses punctually as an adverb?','The parcel arrived punctually before the office closed.','The punctuality arrived before the office closed.','The parcel was punctuality before the office closed.','punctually 修饰 arrived，表示准时到达。',1,'grammar'),q('Which adjective is the base of punctually?','punctual','puncture','pungent','punctually 由 punctual 加 -ly 构成。',1,'word-formation')]);
P('punctuate','Punctuate comes from Latin punctuare, “mark with points”; it means to add punctuation marks or to interrupt a period with repeated events.',[C('punctuate.s1','加标点','The copy editor punctuated the long quotation with commas and a question mark before approving the proof.','文字编辑在批准校样前，给这段长引文加上逗号和问号。','The copy editor punctuated the quotation / with commas and a question mark / before approval.','punctuate.s1 指在文字中加入逗号、句号等标点符号。','编辑在引文中添加逗号和问号。'),C('punctuate.s1','穿插；不时打断','Short bursts of applause punctuated the speaker’s remarks whenever she described a local success.','每当演讲者讲到当地的成功时，短暂的掌声便不时打断她的讲话。','Short bursts of applause punctuated the remarks / whenever the speaker / described a local success.','punctuate 也可比喻指某事不时穿插或打断一个过程。','掌声间歇性地出现在演讲中。')],M('The editor punctuated the quotation by removing every comma, period, and question mark from the text.','The editor punctuated the quotation by adding commas and a question mark where needed.','去掉所有标点是删除标点，不是给文本加标点。','meaning'),[q('Which marks did the copy editor add?','commas and a question mark','a pulley and a pump','a publican and a publisher','编辑给引文添加了逗号和问号。',1,'context'),q('What punctuated the speaker’s remarks?','short bursts of applause','a steady rain puddle','a confidential medical record','掌声不时穿插在讲话中。',1,'context'),q('What does punctuate mean in editing?','insert punctuation marks into writing','publish a book for readers','remove unwanted branches from a shrub','punctuate 可指在文字中加入标点。',1,'meaning'),q('Which Latin verb is related to punctuate?','punctuare, “mark with points”','pulsare, “beat”','pullulare, “sprout”','punctuate 来自表示用点标记的拉丁语动词。',1,'word-formation')]);
P('punctuation','Punctuation comes from Latin punctuatio, from punctuare “mark with points”; it is the system of marks such as commas, periods, and question marks used in writing.',C('punctuation.s1','标点；标点法','The proofreader corrected the punctuation in the instructions so readers would know where each warning ended and the next began.','校对员修改了说明中的标点，使读者清楚每条警告在哪里结束、下一条在哪里开始。','The proofreader corrected the punctuation / so readers could see / where each warning ended.','punctuation 指书写中逗号、句号等标记及其使用规则。','调整标点消除了警告之间的边界歧义。'),M('The proofreader said the paragraph had no punctuation even though it contained periods, commas, and a question mark.','The proofreader said the paragraph had punctuation because it contained periods, commas, and a question mark.','句号、逗号和问号都是标点，不能说段落完全没有标点。','meaning'),[q('Why did the proofreader correct the punctuation?','to show readers where each warning ended','to change the author’s pseudonym','to make the paragraph a public-health report','校对标点是为了区分每条警告的边界。'),q('What is punctuation?','marks such as commas and periods and the rules for using them','a grooved wheel used to lift a bucket','a short burst of light through a sensor','punctuation 指书写标记及其使用规则。',1,'meaning'),q('Which marks are punctuation?','a comma, a period, and a question mark','a pulley, a pump, and a pupa','a publisher, a publican, and a proxy','逗号、句号和问号都是标点。',1,'context'),q('Which related verb means “add marks to writing”?','punctuate','puncture','pulsate','punctuate 是给文字加标点的动词。',1,'word-formation')]);
P('puncture','Puncture comes from Latin punctura, from punctum “a point”; it means to pierce something or the small hole or flat tire caused by piercing.',[C('puncture.s1','刺破；扎孔','A nail punctured the bicycle tire on the trail, so the rider patched the inner tube before continuing.','一颗钉子在小路上刺破了自行车轮胎，骑车人补好内胎后才继续前行。','A nail punctured the bicycle tire / on the trail / so the rider patched the tube.','puncture.s1 作动词表示刺穿或扎出小孔。','钉子在轮胎上造成了孔洞。'),C('puncture.s2','小孔；爆胎','The mechanic found a tiny puncture in the inner tube and sealed it with a rubber patch.','机械师在内胎上发现一个小孔，并用橡胶补片将它封住。','The mechanic found a tiny puncture / in the inner tube / and sealed it.','puncture.s2 作名词可指刺出的孔，也可指由此造成的漏气轮胎。','机械师找到并修补了刺孔。')],M('A nail punctured the bicycle tire by sealing every hole and stopping all the air from escaping.','A nail punctured the bicycle tire by making a hole that let air escape.','刺破是造成孔洞，不是封住孔洞。','meaning'),[q('What damaged the bicycle tire?','a nail on the trail','a comma in the instructions','a short pulse of light','一颗钉子刺破了自行车轮胎。',1,'context'),q('What did the mechanic find in the inner tube?','a tiny hole','a grooved wheel','a small Afghan coin','机械师发现了一个小孔。',2,'context'),q('What does puncture mean as a verb?','pierce and make a small hole','mark writing with a comma','pull a raft toward the riverbank','puncture 作动词表示刺破、扎孔。',1,'meaning'),q('Which sentence uses puncture as a noun?','A puncture in the tire caused it to lose air.','The nail punctured the tire.','The editor corrected the punctuation.','a puncture 指轮胎上的孔洞。',2,'grammar')]);
P('pungent','Pungent comes from Latin pungentem, “pricking or stinging,” from pungere “to prick”; it describes a sharply strong smell or taste.',C('pungent.s1','刺鼻的；辛辣的','The pungent vinegar smell filled the kitchen after the cook opened the bottle.','厨师打开瓶子后，刺鼻的醋味弥漫了厨房。','The pungent vinegar smell filled the kitchen / after the cook / opened the bottle.','pungent 指气味或味道强烈而尖锐，常使感官感到刺激。','醋的强烈气味一开瓶便充满厨房。'),M('The pungent vinegar had no smell or taste and could not be noticed even beside the cook.','The pungent vinegar had a sharp, strong smell that filled the kitchen.','完全没有气味和味道的醋不能称为刺鼻的。','meaning'),[q('What filled the kitchen?','a sharp vinegar smell','a short cloud of smoke from an old stove','a bowl of warm rice pudding','开瓶后刺鼻的醋味弥漫厨房。'),q('What does pungent describe?','a sharply strong smell or taste','an action done exactly on time','a wheel that guides a rope','pungent 描述强烈而尖锐的气味或味道。',1,'meaning'),q('Which taste could be pungent?','a very sharp mustard flavor that stings the nose','plain water with no noticeable taste','a sweet apple with a mild aroma','刺激鼻腔的芥末味可以称为 pungent。',1,'context'),q('Which Latin verb is behind pungent?','pungere, “to prick”','pulsare, “to beat”','purgare, “to clean”','pungent 来自表示刺、扎的拉丁语动词。',1,'word-formation')]);
P('punish','Punish came through Old French puniss- from Latin punire, “to penalize”; it means to impose a penalty or, more broadly, to treat someone or something harshly.',[C('punish.s1','惩罚；处罚','The referee punished the team for deliberately delaying the restart by awarding the other side a free kick.','裁判判给对方任意球，以处罚故意拖延重新开球的球队。','The referee punished the team / for delaying the restart / by awarding a free kick.','punish.s1 指因违规或过错施加处罚。','任意球是对拖延比赛行为的处罚。'),C('punish.s2','严厉对待；重创','The steep final climb punished the cyclists, leaving several of them exhausted before the finish.','最后一段陡坡让骑手们吃尽苦头，几个人还没到终点就已精疲力尽。','The steep final climb punished the cyclists / leaving several / exhausted before the finish.','punish.s2 可比喻指严酷地折磨人或给人造成很大损耗。','陡坡使骑手在比赛结束前筋疲力尽。')],M('The referee punished the team for delaying play by awarding a free kick to the team that committed the delay.','The referee punished the delaying team by awarding a free kick to its opponents.','处罚拖延比赛的一方时，任意球应判给对手。','meaning'),[q('What penalty did the referee award?','a free kick to the other side','a puncture repair to the cyclists','a published study to the team','裁判判给对方任意球作为处罚。',1,'context'),q('What did the final climb do to several cyclists?','left them exhausted before the finish','made them arrive punctually at the start','gave them a bowl of fruit punch','陡坡让几名骑手在终点前筋疲力尽。',2,'context'),q('Which sentence uses punish for a harsh effect?','The long drought punished the crops.','The referee punished the player for a foul.','The editor punctuated the article.','干旱严重损害庄稼，是比喻用法。',2,'meaning'),q('Which Latin verb is related to punish?','punire, “to penalize”','pungere, “to prick”','pulverizare, “to make dust”','punish 经古法语来自表示处罚的拉丁语 punire。',1,'word-formation')]);
P('punishment','Punishment comes from Old French punissement and Latin punire “to penalize”; it names a penalty imposed for breaking a rule or doing wrong.',C('punishment.s1','惩罚；处罚','The school’s punishment for cheating required the student to redo the assignment under supervision.','学校对作弊学生的处罚是要求其在监督下重做作业。','The school’s punishment for cheating / required the student / to redo the assignment.','punishment 指因违反规则或做错事而施加的处罚。','重做作业是针对作弊行为的处罚。'),M('The school called a reward and a public medal the punishment for cheating, even though both honored the student.','The school called supervised work and loss of credit the punishment for cheating.','奖励和奖章是表扬，不是对作弊的处罚。','meaning'),[q('What was the school’s punishment for cheating?','redoing the assignment under supervision','receiving a medal in front of the school','having the assignment published as an example','作弊学生需要在监督下重做作业。'),q('What does punishment mean?','a penalty for breaking a rule or doing wrong','a small pool of water on a path','the quality of being on time','punishment 指针对违规行为施加的惩罚。',1,'meaning'),q('Which action is a punishment for breaking a lab rule?','temporarily losing lab access and completing safety retraining','receiving a prize for following every rule','being asked to choose a pseudonym','暂停实验室权限并补做安全培训是处罚。',1,'context'),q('Which verb is in the history of punishment?','punire','pupare','purgare','punishment 源自表示处罚的拉丁动词 punire。',1,'word-formation')]);
P('pupa','Pupa comes from Latin pupa, “girl or doll”; in biology it names the inactive transformation stage between larva and adult in many insects.',C('pupa.s1','蛹','The butterfly pupa remained attached to the branch until the adult emerged with damp wings.','蝴蝶蛹一直附着在树枝上，直到成虫破蛹而出，翅膀仍湿润。','The butterfly pupa remained attached / until the adult emerged / with damp wings.','pupa 指许多昆虫由幼虫转变为成虫之间的阶段。','蝴蝶在蛹期后才羽化为成虫。'),M('The butterfly’s pupa crawled across the leaves and ate them for weeks before it became a larva.','The caterpillar fed as a larva, then formed a pupa before the adult butterfly emerged.','蛹阶段在幼虫之后、成虫之前；通常不会像幼虫一样取食生长。','meaning'),[q('Where did the butterfly pupa remain?','attached to a branch','inside a public library','under a pulley wheel','蝴蝶蛹附着在树枝上。'),q('What stage comes after the larva and before the adult?','the pupa','the puppy','the publisher','pupa 是幼虫之后、成虫之前的阶段。',1,'meaning'),q('What happened when the adult emerged?','its wings were damp','it became a Roman tax collector','it was turned into paper pulp','蝴蝶成虫刚羽化时翅膀仍湿润。',1,'context'),q('Which Latin word is the source of pupa?','pupa, “girl or doll”','pungere, “to prick”','publicanus, “tax collector”','生物学术语 pupa 直接来自拉丁语 pupa。',1,'word-formation')]);
P('pupate','Pupate is formed from pupa and the verb-forming suffix -ate; it means to enter or develop into the pupal stage.',C('pupate.s1','化蛹','The caterpillar stopped feeding, attached itself beneath a leaf, and pupated before the cold season began.','毛毛虫停止进食，附着在叶片下方，并在寒季开始前化蛹。','The caterpillar stopped feeding / attached beneath a leaf / and pupated before winter.','pupate 指幼虫进入蛹期或发育成蛹。','停止进食后，毛毛虫转入蛹期。'),M('The caterpillar pupated when it hatched from the egg and began feeding as a newly emerged larva.','The caterpillar hatched as a larva, fed, and later pupated beneath a leaf.','孵化后先是幼虫阶段；幼虫之后才化蛹。','meaning'),[q('What did the caterpillar do before it pupated?','stopped feeding and attached beneath a leaf','emerged as an adult with dry wings','punched holes in a paper ticket','毛毛虫停止进食并附着在叶片下方后化蛹。'),q('What does pupate mean?','enter or develop into the pupal stage','hatch directly from an egg as an adult','remove a thorn with tweezers','pupate 指进入蛹期。',1,'meaning'),q('Which sequence is correct for a butterfly?','egg, larva, pupa, adult','pupa, egg, adult, larva','adult, pupa, egg, larva','蝴蝶通常先由卵孵化为幼虫，再化蛹并成为成虫。',1,'context'),q('Which noun is the base of pupate?','pupa','pupil','puppy','pupate 由 pupa 加动词后缀 -ate 构成。',1,'word-formation')]);
P('pupil','Pupil has two histories: the student sense comes through French and Latin pupillus “ward or minor”; the eye sense comes from Latin pupilla, “little doll,” referring to the tiny reflected image in the eye.',[C('pupil.s1','学生；（尤指）小学生','Each pupil received a reading folder and met with the teacher for a short progress conference.','每名学生都领到一个阅读文件夹，并与老师进行了简短的学习进度交流。','Each pupil received a folder / and met with the teacher / for a progress conference.','pupil.s1 指在学校接受教学的儿童或年轻学生。','每名学生都参加了与老师的学习交流。'),C('pupil.s2','瞳孔','The optometrist dimmed the room and watched each pupil contract when a bright light was switched on.','验光师调暗房间，并观察强光打开时每只瞳孔的收缩情况。','The optometrist watched each pupil / contract / when a bright light was switched on.','pupil.s2 指眼睛中央让光线进入的圆形开口。','强光使瞳孔收缩。')],M('The optometrist examined the pupil’s homework to measure how much light entered the center of the eye.','The optometrist examined the pupil of the eye to see how it responded to light.','homework 是学生的作业；让光线进入眼睛的是瞳孔。','meaning'),[q('What did each pupil receive at school?','a reading folder','a contact lens prescription','a dried plum snack','学生每人领到一个阅读文件夹。',1,'context'),q('What did the optometrist watch contract?','the round opening in the center of each eye','the pupils’ homework folders','the eyelid of a butterfly pupa','验光师观察了瞳孔对强光的反应。',2,'context'),q('Which sentence uses pupil to mean a student?','The pupil asked her teacher for help with the assignment.','Bright light caused the pupil to contract.','The optometrist measured the pupil.','向老师求助的 pupil 是学生。',1,'meaning'),q('Why is the eye’s pupil called a “little doll” in its Latin history?','a tiny reflected image can be seen in the eye','it teaches children how to read','it is shaped like a paper ticket','名称与眼中可见的微小倒影有关。',2,'word-formation')]);
P('puppet','Puppet came through French poupette or poupée, “doll”; it can mean a figure moved by strings or a person controlled by someone else.',[C('puppet.s1','木偶','The puppeteer moved the puppet’s wooden hands with thin strings while a musician played behind the screen.','木偶师用细线操纵木偶的木手，幕布后还有乐师演奏。','The puppeteer moved the puppet / with thin strings / while music played behind the screen.','puppet.s1 指由线、手或机械操纵的人形或动物形偶像。','木偶的动作由木偶师通过细线控制。'),C('puppet.s2','傀儡；受人操纵者','The committee rejected the accusation that its chair was a puppet controlled by outside donors.','委员会否认了外界捐助者操纵主席、使其成为傀儡的指控。','The committee rejected the accusation / that its chair was a puppet / controlled by outside donors.','puppet.s2 比喻指完全受他人控制的人或组织。','指控称主席受捐助者控制。')],M('The committee called its independent chair a puppet even though no donor could influence or control any decision.','The committee called its chair a puppet because outside donors controlled every decision.','若主席不受外界控制，就不能据此称其为傀儡。','meaning'),[q('How was the puppet moved?','the puppeteer operated it with thin strings','a pulley raised it through the well','the pupa’s wings carried it across the room','木偶师用细线操纵木偶。'),q('Why did critics call the chair a puppet?','they alleged outside donors controlled the chair','the chair was made of wood and moved by strings','the chair published a report under a pseudonym','批评者指控主席受外界捐助者操纵。',2,'context'),q('Which meaning is figurative?','a leader who follows another person’s orders','a small figure moved by strings','a carved wooden toy on a stage','受别人操控的领导者是 puppet 的比喻义。',2,'meaning'),q('Which French word is part of puppet’s history?','poupette or poupée, “doll”','poudre, “powder”','pomme, “apple”','puppet 经法语中表示玩偶的词进入英语。',1,'word-formation')]);
P('puppetry','Puppetry is formed from puppet and -ry; it means the craft or performance of operating puppets.',C('puppetry.s1','木偶操纵术；木偶戏','The theater’s puppetry workshop taught students how to coordinate hand movements, strings, and dialogue.','剧院的木偶戏工作坊教学生如何协调手部动作、牵线和对白。','The puppetry workshop taught students / to coordinate hand movements / strings, and dialogue.','puppetry 指操纵木偶的技艺或以木偶进行的表演。','工作坊教授操偶动作、牵线和对白协调。'),M('The museum defined puppetry as the craft of writing weather reports and measuring rainfall, with no puppets involved.','The museum defined puppetry as the craft of operating puppets in a performance.','写天气报告和测量降雨与木偶操纵无关。','meaning'),[q('What did the puppetry workshop teach?','coordinating movement, strings, and dialogue','measuring the pupil of an eye','publishing a history book','工作坊讲授木偶动作、牵线与对白协调。'),q('What is puppetry?','the craft or performance of operating puppets','the medical treatment of mental disorders','a method of making fruit pulp','puppetry 指操纵木偶的技艺或表演。',1,'meaning'),q('Which event features puppetry?','a stage show in which performers manipulate figures behind a screen','a public-health meeting about vaccination','a clinic appointment to check a pulse','幕后操纵木偶的舞台表演属于 puppetry。',1,'context'),q('Which suffix appears in puppetry?','-ry, forming a craft or practice noun','-ly, forming an adverb','-ate, forming a verb','puppet 加 -ry 构成表示技艺的名词。',1,'word-formation')]);
P('puppy','Puppy is an English word recorded from the 16th century, probably influenced by French poupée “doll”; its deeper history is uncertain. It means a young dog.',C('puppy.s1','小狗；幼犬','The shelter placed a puppy with a foster family that could provide patient training and regular walks.','收容所把一只幼犬安置给寄养家庭，对方能耐心训练并定期遛狗。','The shelter placed a puppy / with a foster family / for training and walks.','puppy 指尚幼的狗。','寄养家庭为幼犬提供训练和照料。'),M('The shelter called the puppy an adult dog even though it was only a few weeks old and still needed its mother.','The shelter called the few-week-old dog a puppy and arranged a foster home for it.','只有几周大、仍需照料的狗是幼犬，不是成年犬。','meaning'),[q('What did the foster family agree to provide?','patient training and regular walks','a public vote and a proxy form','a bowl of fruit punch','寄养家庭为幼犬提供训练和遛狗照料。'),q('What is a puppy?','a young dog','an adult butterfly between larva and emergence','a person controlled by a donor','puppy 指幼犬。',1,'meaning'),q('Which animal would normally be called a puppy?','a small dog not yet fully grown','a mature wolf in the wild','a pterosaur fossil in a museum','尚未长大的小狗称为 puppy。',1,'context'),q('Which possible French influence is mentioned in puppy’s uncertain history?','poupée, “doll”','pouls, “pulse”','poudre, “powder”','puppy 的词源可能受法语“玩偶”一词影响。',1,'word-formation')]);
P('purchase','Purchase comes from Anglo-French purchacer, “seek or procure”; it means to buy something, the thing bought, or a firm hold that prevents slipping.',[C('purchase.s1','购买','The lab purchased a replacement sensor after the old one failed during the final trial.','旧传感器在最后一次试验中损坏后，实验室购买了替换件。','The lab purchased a replacement sensor / after the old one failed / during the trial.','purchase.s1 作动词表示购买某物，常见于正式或商务语境。','实验室付费购入了替换传感器。'),C('purchase.s2','购买的物品；购买行为','The receipt listed each purchase separately so the department could track its monthly equipment spending.','收据逐项列出每笔购买，以便部门跟踪每月设备支出。','The receipt listed each purchase / separately / to track equipment spending.','purchase.s2 作名词可指买下的东西或购买行为。','收据记录每项买入物品或支出。'),C('purchase.s3','紧握；着力点','The climber found purchase on a narrow ledge and paused before reaching for the next hold.','登山者在狭窄岩架上找到着力点，伸手够下一个支点前停了一下。','The climber found purchase / on a narrow ledge / before reaching for the next hold.','purchase.s3 指牢固抓握或不打滑的着力点。','岩架提供了稳固支撑，让登山者不致滑落。')],M('The climber lost purchase on the wet rock because the smooth surface gave her a firm, nonslip grip.','The climber gained purchase on the rough rock because it gave her a firm, nonslip grip.','firm grip 表示抓牢而不是失去着力点。','meaning'),[q('What did the lab purchase?','a replacement sensor','a bowl of pudding','a publican’s tax record','实验室购买了一个替换传感器。',1,'context'),q('What did the receipt list separately?','each item bought by the department','each student’s pupil in a class','each pupa attached to a branch','收据逐项列出每次购买。',2,'context'),q('What did purchase mean for the climber?','a firm grip or foothold on the ledge','the act of buying a sensor','a printed book from a publisher','登山者在岩架上找到的是稳固着力点。',3,'meaning'),q('Which sentence uses purchase as a verb?','The hospital purchased a new scanner.','The receipt showed the purchase.','The climber found purchase on the ledge.','hospital purchased 表示医院买下了扫描仪。',1,'grammar')]);
P('pure','Pure comes from Old French pur and Latin purus “clean or unmixed”; it can describe an unmixed substance, something complete in degree, or moral innocence.',[C('pure.s1','纯的；不含杂质的','The chemist used pure distilled water so dissolved minerals would not affect the experiment.','化学家使用纯蒸馏水，以免溶解矿物质影响实验。','The chemist used pure distilled water / so minerals / would not affect the experiment.','pure.s1 指未混入其他物质或杂质的。','蒸馏水不含会干扰实验的矿物质。'),C('pure.s2','纯粹的；完全的','The sudden cancellation was pure bad luck; every permit had been approved the day before.','突然取消纯属倒霉；所有许可证前一天都已获批。','The cancellation was pure bad luck / because every permit / had already been approved.','pure.s2 可表示完全的、纯粹的程度或性质。','取消与许可证无关，原因只是运气不好。'),C('pure.s3','纯洁的；清白的','The witness’s motives were pure: she reported the hazard only because she wanted workers to stay safe.','证人的动机很纯正：她报告危险仅仅是希望工人保持安全。','The witness’s motives were pure / because she wanted / workers to stay safe.','pure.s3 指道德上清白、没有恶意或不当动机。','证人报告危险是为了保护工人。')],M('The chemist called the water pure even though a large amount of salt and mineral residue remained dissolved in it.','The chemist called the water impure because dissolved salt and minerals remained in it.','含有大量溶解盐和矿物质的水并非纯水。','meaning'),[q('Why did the chemist use pure distilled water?','to prevent minerals from affecting the experiment','to add extra minerals to the sample','to make the report more public','纯蒸馏水避免矿物质干扰实验。',1,'context'),q('What caused the cancellation in the second example?','pure bad luck after permits had been approved','a deliberate failure to apply for permits','a public-health warning about water','许可证获批后仍取消，被说成纯属倒霉。',2,'context'),q('What does pure mean about the witness’s motives?','morally innocent and without a harmful aim','free from all dissolved minerals','complete in degree but morally wrong','证人出于保护工人的目的，动机纯正。',3,'meaning'),q('Which Latin adjective is the source of pure?','purus, “clean or unmixed”','pupa, “doll”','punctus, “a point”','pure 经古法语来自表示洁净、未混合的拉丁语 purus。',1,'word-formation')]);
P('puree','Puree comes from French purée, a preparation of food pressed or strained into a smooth paste; it names that soft, uniform food.',C('puree.s1','泥；糊状食物','The chef pureed the roasted carrots into a smooth puree for the infant’s first meal.','厨师把烤胡萝卜打成细滑的糊状食物，作为婴儿的第一餐。','The chef pureed the carrots / into a smooth puree / for the infant.','puree 指把熟食压碎、搅打或过筛后制成的细滑糊状食物。','胡萝卜被加工成适合婴儿食用的软糊。'),M('The chef served a puree made of whole, hard carrots that had not been cooked, crushed, or strained.','The chef served a puree made by cooking and blending the carrots until smooth.','未煮熟且完整坚硬的胡萝卜不是糊状食物。','meaning'),[q('What did the chef turn into a puree?','roasted carrots','a paper ticket','a handful of dry pumice','厨师把烤胡萝卜打成细滑糊状。'),q('What is puree?','food pressed or blended into a smooth paste','a young dog','a short pulse of light','puree 指压碎或搅打成糊的食物。',1,'meaning'),q('Which dish is a puree?','smooth blended pumpkin served with soup','whole uncooked carrots served intact','a crisp paper ticket with holes','搅打细滑的南瓜可以作为 puree。',1,'context'),q('Which language supplied puree to English?','French','Scottish Gaelic','Greek','puree 来自法语 purée。',1,'word-formation')]);
P('purely','Purely is formed from pure and -ly; it means only or entirely, often emphasizing that no other motive or ingredient is involved.',C('purely.s1','仅仅；完全地','The committee chose the route purely for safety reasons, not because it was shorter or cheaper.','委员会选择这条路线纯粹出于安全考虑，而不是因为它更短或更便宜。','The committee chose the route purely for safety reasons / not because / it was shorter or cheaper.','purely 修饰原因或程度，表示仅仅、完全出于某一因素。','例句明确排除了路线长度和价格这两个动机。'),M('The committee chose the route purely for safety reasons but also because it was the cheapest and most convenient option.','The committee chose the route partly for safety and partly because it was the cheapest and most convenient option.','若同时考虑安全、价格和便利，就不能说纯粹出于安全。','meaning'),[q('Why did the committee choose the route?','only for safety reasons','because it was shorter and cheaper','because a publisher recommended it','委员会选择路线纯粹出于安全考虑。'),q('What does purely mean?','only or entirely','at the appointed time','with a sharply strong smell','purely 表示仅仅或完全地。',1,'meaning'),q('Which sentence uses purely to limit a motive?','She accepted the role purely to help the neighborhood.','She arrived purely at 7:30 on the dot.','The purely vinegar smell filled the room.','“纯粹为了帮助社区”限定了接受职位的动机。',1,'context'),q('Which adjective is purely formed from?','pure','pupil','punctual','pure 加 -ly 构成 purely。',1,'word-formation')]);
P('purge','Purge comes through Old French purgier from Latin purgare “cleanse”; it can mean removing disloyal members, cleansing guilt or impurities, or a campaign of removal.',[C('purge.s1','清洗；清除（异己）','The new chair tried to purge the committee of members who had falsified grant records.','新任主席试图清除委员会中伪造拨款记录的成员。','The chair tried to purge the committee / of members / who falsified grant records.','purge.s1 指从组织中清除被视为不忠或不合意的成员。','清除对象是伪造记录的委员会成员。'),C('purge.s2','净化；洗清','After confessing the lie, he hoped that an honest apology would purge his lingering guilt.','承认说谎后，他希望真诚道歉能够洗去心中挥之不去的愧疚。','He hoped an honest apology / would purge / his lingering guilt.','purge.s2 可表示从内心清除罪疚或不良情绪，也可指净化。','道歉被视为洗清愧疚的方式。'),C('purge.s3','大清洗（运动）','Historians described the purge as a campaign in which thousands of officials were removed from their posts.','历史学家把这场大清洗描述为一次大规模免去数千名官员职务的运动。','Historians described the purge / as a campaign / that removed thousands of officials.','purge.s3 作名词可指有组织地大规模清除成员的行动。','许多官员在一次集中行动中被免职。')],M('The chair purged the committee of loyal members who had never falsified records and kept every corrupt official in place.','The chair purged the committee of members who had falsified grant records.','purge 在此是清除被认为不合格的成员，不能说清除忠实清白者而保留舞弊者。','meaning'),[q('Whom did the new chair try to remove?','members who falsified grant records','the historians who wrote about the committee','the neighbors who attended a public meeting','主席试图清除伪造拨款记录的成员。',1,'context'),q('What did the apology aim to purge?','the speaker’s lingering guilt','the committee’s published schedule','the bicycle tire’s puncture','道歉希望洗去心中的愧疚。',2,'context'),q('What did historians call the mass removal of officials?','a purge','a puree','a pupa','大规模免去官员职务称为 purge。',3,'context'),q('Which Latin verb is the origin of purge?','purgare, “cleanse”','pungere, “prick”','pulsare, “beat”','purge 经法语来自表示净化的拉丁语 purgare。',1,'word-formation')]);
P('purification','Purification is formed from purify and -cation, ultimately from Latin purificare, “make clean”; it means removing impurities or cleansing in a religious or symbolic sense.',[C('purification.s1','纯化；涤净','The purification system removes metal particles from the water before it reaches the laboratory taps.','纯化系统会在水流到实验室水龙头前去除其中的金属颗粒。','The purification system removes particles / from the water / before it reaches the taps.','purification 指去除杂质使物质变纯，也可指宗教或象征意义上的净化。','系统从水中去除金属颗粒。'),C('purification.s1','净化；涤净','The ceremony included a symbolic purification intended to mark the community’s fresh start.','仪式包含象征性的净化环节，用来标志社区重新开始。','The ceremony included symbolic purification / intended to mark / a fresh start.','purification 也可指宗教或象征仪式中的净化行为。','社区仪式用净化象征新的开始。')],M('The purification system added more metal particles to the water and left the contaminants in place.','The purification system removed metal particles and other contaminants from the water.','纯化是去除污染物，不是把杂质加进水里。','meaning'),[q('What did the purification system remove from the water?','metal particles','the laboratory taps','the ceremony’s fresh start','系统去除了水中的金属颗粒。',1,'context'),q('What did purification symbolize in the ceremony?','the community’s fresh start','the return of contaminants to the water','the cancellation of a public meeting','仪式中的净化象征社区重新开始。',1,'context'),q('What does purification mean?','removing impurities or cleansing','adding pollutants to a substance','making a public announcement','purification 指去除杂质或进行净化。',1,'meaning'),q('Which verb is purification related to?','purify','publish','punctuate','purification 与 purify 同词族。',1,'word-formation')]);
P('purified','Purified is the past participle and adjective of purify; it describes a substance or person freed from impurities or treated through a purification process.',C('purified.s1','已提纯的；已净化的','The purified sample contained no detectable metal particles after passing through the new filter.','样本通过新过滤器后已被提纯，检测不到金属颗粒。','The purified sample contained no particles / after passing / through the new filter.','purified 表示经过处理、去除了杂质或污染物。','检测结果表明金属颗粒已被过滤。'),M('The lab called the sample purified even though testing found more metal particles in it than before filtration.','The lab called the sample purified after testing found that the filter had removed the metal particles.','过滤后杂质反而更多，不能说样本已经提纯。','meaning'),[q('What was absent from the purified sample?','detectable metal particles','a published journal article','a pupa attached to a branch','过滤后的样本检测不到金属颗粒。'),q('What does purified mean?','freed from impurities by a process','made public for readers','arrived at the scheduled time','purified 指经处理去除了杂质。',1,'meaning'),q('Which liquid is purified?','water passed through a filter that removes contaminants','water with extra metal fragments added','an untested liquid in a sealed bottle','过滤去除污染物后的水已被净化。',1,'context'),q('Which verb is the base of purified?','purify','puree','punish','purified 是 purify 的过去分词形式。',1,'grammar')]);
P('purify','Purify came through Old French purifier from Latin purificare, “make clean,” from purus “pure” and facere “make”; it means removing dirt or impurities.',C('purify.s1','净化；提纯','The researchers purify the drinking water with a carbon filter before testing it for microbes.','研究人员先用活性炭过滤器净化饮用水，再检测微生物。','The researchers purify the water / with a carbon filter / before testing it.','purify 指去除杂质、污物或污染物使某物变纯净。','过滤器在微生物检测前去除水中杂质。'),M('The researchers purify the water by adding untreated sewage and leaving every contaminant in the sample.','The researchers purify the water by filtering out contaminants before testing it.','加入污水并保留污染物会污染水，不是净化。','meaning'),[q('What do researchers use to purify the drinking water?','a carbon filter','a proxy form','a grooved pulley','研究人员用活性炭过滤器净化水。'),q('What does purify mean?','make something clean by removing impurities','make a report available to the public','make a short wave of light','purify 指去除杂质使某物洁净。',1,'meaning'),q('Why purify water before testing it for microbes?','to remove contaminants that could affect the sample','to add sewage so more microbes appear','to change the water into paper pulp','先过滤杂质可减少污染物对样本检测的干扰。',1,'context'),q('Which Latin elements are reflected in purify?','purus “pure” + facere “make”','pupa “doll” + -ate','pungentem “pricking” + -ly','purify 来自表示“纯”和“使”的拉丁语词素。',1,'word-formation')]);
})();
